INSERT INTO temp_import_pages VALUES ('{"pageId": "e0410000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 41, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "41", "printedPageNumber": 41, "pdfPageNumber": 424, "sequenceIndex": 31, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0410000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "for neglecting Maghrib and till dawn for neglecting Ishaa. The serpent will keep on thrashing him thus till the Last Day. Each blow pushes him to a depth of seventy arm''s length. The punishments will last till the Day of Judgement.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Those after resurrection are: His reckoning will be a hard one; Allah will be angry with him; and he will be thrown into the Fire. According to one report, he will have following three lines inscribed on his forehead:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "''O you who neglected Allah''s duty''\n''O you who has deserved Allah''s wrath.''\n''Now despair of Allah''s mercy, as you neglected your duty to Allah.''", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Eminent theologians like Ibn Hajr, Abu Laith Samarqandi (Rahmatullah alaihim), and others, have mentioned this hadith in their books. Although I have not been able to trace the text in original books on hadith, yet other hadiths, some of which have already been mentioned and some are to follow, corroborate its meaning. Neglect of salaat, as has been stated above, leads one to kufr; hence no punishment is too severe for this offence. But it should be borne in mind that even after the declaration of a person as being guilty, Allah is free to pardon him as and when He pleases. He says in His Holy Book:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَنْ يَشَاءُ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! Allah pardoneth not that partners should be ascribed unto Him. Allah pardoneth all (save that) whom He will. (IV: 116)\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "If then it pleases Allah to pardon anybody neglecting salaat, it will be most fortunate; but who can be sure of this fortune?", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}, {"id": "f0410800-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is also stated in hadith that there will be three courts to be held by Allah on the Day of Judgement. The first will judge between kufr and islaam and there will be no pardon. The second will be to judge the duties and conduct of one towards another. All aggrieved shall be compensated there; compensation will either be realised from the aggressor or paid by Allah Himself, if He pleases to pardon anybody. The third will deal with duties towards Allah. Here the doors of Allah''s mercy will be thrown wide-open and He shall pardon anybody He wills. In the light of all that has", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 41"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0420000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 42, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "42", "printedPageNumber": 42, "pdfPageNumber": 425, "sequenceIndex": 32, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0420000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "been said above, it must be clearly understood that we deserve the punishments that have been laid down for our commission of sins, but the All-embracing mercy of Allah overrides everything and knows no bounds.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It was a habit with the Prophet (Sallallaho alaihe wasallam) to enquire from the companions, just after Fajr, if anybody had seen any dream. He would then interpret the dream as related to him. One day, after enquiring from others as usual, the Prophet (Sallallaho alaihe wasallam) himself narrated a long dream in which two men came and took him with them. Besides others he reported certain events which he happened to see in his dream. He said: \"I noticed the head of a person being crushed with a heavy stone. It was struck with such force that, after crushing the head, the stone rolled down over a long distance. The head would assume its normal shape by the time the stone was brought back for repeating the process. This continued incessantly. On inquiring from one of my companions, I was told that the person first learnt the Qur''an, but failed to practise upon it and also used to go to sleep without offering the fardh salaat.\" There is another similar narration, in which the Prophet (Sallallaho alaihe wasallam) is reported to have seen (in his dream) a group of people being treated likewise. Jibra-eel (Alayhis salaam) informed him on his query that those were the persons who used to neglect their salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Mujahid (Rahmatullah alaih) says, \"Allah blesses the people who guard their salaat, just as He blessed Hadhrat Ibrahim (Alayhis salaam) and his descendants.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"If a person dies with sincere Imaan, observing the commandments of Allah, performing salaat, and paying Zakaat, when he dies Allah is pleased with him.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas (Radhiyallaho anho) also narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Allah says, ''I hold back retribution, deserved by a locality, when I see therein some people who frequently visit the musjid, love one another for My sake, and pray for forgiveness in the hours of darkness.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}, {"id": "f0420600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Darda (Radhiyallaho anho) wrote to Hadhrat Salmaan: \"Spend most of your time in the musjid. I have heard the Prophet (Sallallaho alaihe wasallam) saying, ''The musjid is the abode of the pious. Allah has taken upon Himself to bless the person who spends most of", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 42"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0430000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 43, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "43", "printedPageNumber": 43, "pdfPageNumber": 426, "sequenceIndex": 33, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0430000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "his time in the mosque. Allah shall keep him in comfort and shall make him cross the Siraat with great ease. Surely Allah is pleased with such a person.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Mas''ood (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"The masaajid are the Houses of Allah, and people coming therein are His visitors. When everybody treats his visitors kindly, why should Allah not be kind to His guests?\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"Allah loves the person who is attached to the musjid.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"When a dead person is laid in the grave, even before the people present at his burial clear off, Munkar and Nakeer visit him. Then, if the person is a Mo''min, his good practices encircle him; salaat comes close to his head, Zakaat to his right, Fast to his left, and the remaining good deeds towards his feet, so that none can approach him. Even the angels do the necessary questioning while standing at a distance.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "One of the companions reports that, when the inmates of the Prophet''s house were hard-pressed in any way, he would enjoin salaat on them and recite the following verse:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَى", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And enjoin salaat upon thy people and be constant therein. We ask not of thee a provision, We provide for thee. And the Hereafter is for the righteousness.\" (XX: 132).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430800-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Asma (Radhiyallaho anha) narrates that she heard the Prophet (Sallallaho alaihe wasallam) saying, \"All the people will be gathered together on the Day of Judgement and they will all hear the voice of the announcing angel. He will say, ''where are those who glorified Allah in ease and adversity?'' A group will rise up and enter Paradise without reckoning. It will then be announced, ''where are those who forsook their beds and spent their nights in worship?'' Another group will rise up and enter Paradise without reckoning. The angel will again announce, ''where", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0440000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 44, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "44", "printedPageNumber": 44, "pdfPageNumber": 427, "sequenceIndex": 34, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0440000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "are those whom trade and business did not distract from remembrance of Allah?'' Yet another group will rise up and enter Paradise.\" In another hadith, the same account is given, with the addition that in the beginning the angel will say, \"All those gathered here will see today who are the honoured people\", and with the modification that the angel at the time of third announcement will say, ''Where are those whom their engagement in trade and business did not distract from salaat and remembrance of Allah?''", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Sheik Nasr Samarqandi (Rahmatullah alaih), after quoting this Hadith writes, \"When all the three groups will have entered Paradise without reckoning, a monster with a long neck, shining eyes and most eloquent tongue will rise up from Hell and say, ''I have been deputed on all who are proud and ill-tempered.'' It will then pick up all such persons from the crowd, as a fowl picks up grain and then it will fling them into the Hell. It will rise up again saying, ''This time I have been deputed on all who maligned Allah and His Apostle (Sallallaho alaihe wasallam).'' It will then pick up all such persons and throw them into the Hell; it will appear for the third time and will, in a similar manner, take away all those who made images and pictures. The reckoning will then commence after these three groups have been eliminated.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said that during the early times people could see Satan. A person approached him saying how could he be like him. Satan told him that he had never received such a request before and asked him what had prompted him to ask for it. The person told him that he wished it from his heart. Satan told him to neglect his salaat and to swear very frequently, not caring whether he was doing it truthfully. The person told Satan that he would swear by Allah never to give up salaat and swear falsely. Satan told him that never before had he been tricked by a human being to seek his advice. He was determined never to do so in future.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Ubayy (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Give glad tidings to the Muslims that they shall be honoured and exalted, and their religion shall prevail, but there is no portion in the Hereafter for those who exploit Islam for worldly gains.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}, {"id": "f0440500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) is reported to have said, \"I saw Allah in His best form. He said to me, ''O Muhammad! what are the Highest Chiefs (Angels) arguing about?'' I said, ''I have no knowledge about that.'' Allah", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 44"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0450000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 45, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "45", "printedPageNumber": 45, "pdfPageNumber": 428, "sequenceIndex": 35, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0450000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "placed His gracious hand on my bosom. I felt its solacing coolness right through my heart, and the entire universe was revealed to me. I said, ''They are arguing about the things which exalt, the things which atone for the sins, the rewards for the paces taken while going for salaat (with Jamaat), the virtues of performing wudhu properly when it was very cold, and the blessings that a person deserves when after performing one salaat he keeps on sitting in musjid till the next salaat.'' A person particular of these shall live a blessed life and shall die an enviable death.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) is reported (in many ahaadith) to have said, \"Allah says, ''O, Son of Aadam! Say four rakaats of salaat in the early part of the day. I shall help thee in accomplishing all thy jobs during the rest of the day.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said in a hadith: \"Salaat is the cause of Allah''s pleasure, is loved by the Angels, is a tradition of the Prophets, gives enlightenment about Allah, causes the prayers to be granted, blesses the daily bread, is the root of Imaan, refreshes the body, is a weapon against the enemy, shall intercede for its adherent, is a light in the darkness and a companion in the loneliness of the grave, is a reply to the questioning of Angels, is a shade against the Sun on the Day of Judgement, is a protection against the fire of Hell, is a weight for the scales of good deeds, is a means of swift crossing over the Siraat and is a key to Paradise.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Uthman (Radhiyallaho anho) is reported to have said, \"Allah bestows nine favours on a person who guards his salaat and is particular in performing it at its appointed hours: viz: He is loved by Allah, he enjoys good health, is constantly under the protection of angels, his home is blessed, the light of righteousness shines on his face, his heart is made soft, he shall cross the Siraat with the speed of lightning, he is saved from Hell, and his neighbours in Paradise are those about whom Allah has said,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "''There shall be no fear come upon them, neither shall they grieve (II: 36).''", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}, {"id": "f0450700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) says, \"Salaat is the Pillar of Islam and it has ten virtues, viz: It is a charm of the face, a light of the heart, health and refreshment for the body, a company in the grave, a means for the descent", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 45"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0460000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 46, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "46", "printedPageNumber": 46, "pdfPageNumber": 429, "sequenceIndex": 36, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0460000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 46"}, {"id": "f0460100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "of Allah''s Mercy, a key to the Heaven, a weight of the scales (of good deeds), a means of winning Allah''s pleasure, a price of Paradise and a protection against the fire of Hell. A person who is particular of salaat, in fact, establishes deen and one who neglects it demolishes (so to say, the structure of) deen.\n\nAccording to one hadith, there is healing in salaat. Once the Prophet (Sallallaho alaihe wasallam) saw Hadhrat Abu Hurairah (Radhiyallaho anho) lying on his stomach. He said to him, \"Are you suffering from stomach pain?\" He replied in the affirmative. The Prophet (Sallallaho alaihe wasallam) said, \"Then get up and busy yourself in salaat, for that will heal you.\"\n\nOnce the Prophet (Sallallaho alaihe wasallam), in his dream, saw Paradise and heard the footsteps of Hadhrat Bilaal (Radhiyallaho anho) there. Next morning he said to Bilaal: \"What deed of yours helped you to follow me even to Paradise?\" He replied: \"When my wudhu breaks even at night, I take a fresh wudhu and say as many ''rakaats'' of nafl salaat as I can.\"\n\nSafeeri (Rahmatullah alaih) writes: \"The Angels address a person who misses Fajr as ''O you wrongdoer'', and one who neglects Zuhr as ''O you loser'', and one who ignores Asr as ''O you transgressor'', and one who omits Maghrib as ''O you Kaafir'', and one who does not say Ishaa as ''O you violator of Allah''s commandments.''\"\n\nAlama Sha''raani (Rahmatullah alaih) writes: \"It should be clearly understood that a calamity is drawn off from a locality the people of which are particular about salaat, whereas a locality the people of which neglect salaat is frequently visited by calamities. Earthquakes, thunderbolts and sinking of houses are not unexpected where people are not particular about salaat. Simply guarding one''s own salaat is not enough, because when a calamity strikes, it does not befall the wrongdoers alone. It affects everybody in that locality. Once the Sahabah asked the Prophet (Sallallaho alaihe wasallam): ''Can we perish while there are pious people among us?'' the Prophet (Sallallaho alaihe wasallam) replied, ''Yes, if vice becomes predominant.'' It is therefore necessary that other people should also be enjoined to stick to Allah''s commandments and refrain from wrongdoing.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 46"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0470000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 47, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "47", "printedPageNumber": 47, "pdfPageNumber": 430, "sequenceIndex": 37, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0470100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith VIII", "sourceIdentifier": "VIII", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0470000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 47"}, {"id": "f0470100-0000-4000-8000-000000000001", "structuralNodeId": "b0470100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith VIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 47"}, {"id": "f0470200-0000-4000-8000-000000000001", "structuralNodeId": "b0470100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "روي أنه عليه الصلاة والسلام قال من ترك الصلاة حتى مضى وقتها ثم قضى عذب في النار حقبا والحقب ثمانون سنة والسنة ثلاثمائة وستون يوما كل يوم كان مقداره ألف سنة هكذا في مجالس الأبرار", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 47"}, {"id": "f0470300-0000-4000-8000-000000000001", "structuralNodeId": "b0470100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) is reported to have said, \"A person neglecting his salaat (even though he makes it up later) shall remain in Hell for a period of one Haqb. A Haqb is equal to eighty years of three hundred and sixty days each, and a day in the Hereafter shall equal one thousand years of this world.\"\n\nAbul Laith Samarqandi (Rahmatullah alaih) is responsible for the hadith in which the Prophet (Sallallaho alaihe wasallam) is reported to have said, \"The name of a person who neglects even a single fardh salaat intentionally is written on the gate of the Hell, which he must enter.\" Hadhrat Ibn Abbas (Radhiyallaho anho) narrates that once the Prophet (Sallallaho alaihe wasallam) said, \"Pray, O Allah! cause not any one of us to be a wretched destitute.\" He then said: \"Do you know who is a wretched destitute?\" At the request of the companions, he explained to them saying, \"A wretched destitute is he who neglects his salaat. In Islaam there is nothing for him.\" In another hadith it is said, \"Allah will not care a bit for the person who has been neglecting salaat intentionally, and for him shall be an awful doom.\"\n\nIt is reported in a hadith that ten persons will be specially tormented, and one of them will be the person who neglects his salaat. It is said that his hands will be tied while the angels shall smite him on his face and back. Paradise will tell him, ''In me there is no room for you,'' and Hell will say to him, ''Come to me. You are for me and I am for you.'' It is also reported that there is a valley in Hell named Lamlam. This valley is infested with serpents as fat as the neck of a camel and as long as one month''s journey. A person neglecting salaat shall be tormented in this valley. In another hadith, it is reported that there is a vale in the Hell, which is known as the Pit of Grief; it is infested with scorpions of the size of a mule. This place is also meant for tormenting the people who neglect salaat. Of course, there is nothing to worry if the most merciful Allah", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 47"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0480000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 48, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "48", "printedPageNumber": 48, "pdfPageNumber": 431, "sequenceIndex": 38, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0480100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith IX", "sourceIdentifier": "IX", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0480000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}, {"id": "f0480100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "pardons the sins. But are we really prepared to ask for His pardon?\n\nIbn Hajar writes, \"A woman died. Her brother was present at her burial. By chance his purse fell into the grave and was buried with the dead body. The brother realized this after he had returned home and was very sorry for the loss. He decided to dig up the grave secretly and take out the purse. When he dug it up, he saw that the pit was in flames. He returned home, stricken with grief, and related the story to his mother, and inquired if she knew why it was so. The mother informed him that his sister used to delay in salaat and offered it after its fixed hours. May Allah save us from these habits!", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}, {"id": "f0480200-0000-4000-8000-000000000001", "structuralNodeId": "b0480100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith IX", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}, {"id": "f0480300-0000-4000-8000-000000000001", "structuralNodeId": "b0480100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ لا سهم في الإسلام لمن لا صلاة له ولا صلاة لمن لا وضوء له أخرجه البزار وأخرج الحاكم عن عائشة مرفوعا وصححه قلت أظن لا سهم لمن لا صلاة له سهم في الإسلام كمن لا سهم له وسهام الإسلام الصوم والصلاة والصدقة الحديث وأخرج الطبراني في الأوسط عن ابن عمر مرفوعا لا دين لمن لا صلاة له إنما موضع الصلاة من الدين كموضع الرأس من الجسد كذا في الدر المنثور", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}, {"id": "f0480400-0000-4000-8000-000000000001", "structuralNodeId": "b0480100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"There is no place in Islaam for a person who does not say his salaat, and there is no salaat without wudhu.\" Hadhrat Abdullah bin Umar (Radhiyallaho anho) also heard the Prophet (Sallallaho alaihe wasallam) saying, \"There is no Islaam in a person when there is no salaat by him. The position of salaat in Islaam is as the position of the head in a body.\"\n\nLet those who do not offer salaat, and not only call themselves Muslims, but also boast of their being champions of the Muslim cause, ponder over these words of the Holy Prophet (Sallallaho alaihe wasallam). They dream of reviving the past glory of Islaam, but would not care to know how rigidly the people responsible for that glory stuck to the practices of Islaam.\n\nHadhrat Abdullah bin Abbas (Radhiyallaho anho) suffered from cataract of the eye. People told him that the disease could be treated, but he would have to miss his salaat for a few days. He said: \"This is not possible; I have heard", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 48"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0490000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 49, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "49", "printedPageNumber": 49, "pdfPageNumber": 432, "sequenceIndex": 39, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0490000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 49"}, {"id": "f0490100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "the Prophet (Sallallaho alaihe wasallam) saying, \"A person who does not say his salaat shall stand before Allah while Allah shall be angry with him.\" The companions of the Prophet would rather like to go blind than to forego salaat (though permissible under such circumstances) even for a few days. When on his last day Hadhrat Umar (Radhiyallaho anho) was stabbed by a Majoos, he often remained unconscious and eventually died due to excessive bleeding. While on his death-bed, he was made conscious of the approaching salaat hours and he performed salaat in that very condition, and would remark: \"There is no lot in Islaam for a person who does not say his salaat.\" These days it is considered unkind and improper to induce the patient or even allow him to say his salaat. What a world of difference is there between the view-points and approach of the Muslims of these two ages!\n\nHadhrat Ali (Radhiyallaho anho) once requested the Prophet (Sallallaho alaihe wasallam) to give him a servant. The Prophet (Sallallaho alaihe wasallam) said \"Here are three slaves; take anyone you like.\" Hadhrat Ali (Radhiyallaho anho) said, \"You may kindly choose one for me.\" The Prophet (Sallallaho alaihe wasallam) pointed towards a certain man and said, \"Take this one; he is particular about his salaat. But you are not to beat him. We are forbidden to beat one who says salaat.\" We, on the other hand, mock at our servant and consider him a liability if he goes for salaat.\n\nSufyaan Thauri (Rahmatullah alaih), the famous Soofi once fell into a state of ecstasy. He remained in his house for seven days without sleep, food and drink. When his Shaikh was informed of his condition, he inquired if Sufyaan was observing the hours of his salaat. He was told that his salaat was quite regular and safe. At this, the Shaikh remarked, \"Glory be to Allah, Who has not allowed the Devil to have an upper hand on him!\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 49"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0500000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 50, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "50", "printedPageNumber": 50, "pdfPageNumber": 433, "sequenceIndex": 40, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0500100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "IMPORTANCE OF JAMAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0500200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER I", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0500300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "REWARDS OF JAMAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0500400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith I", "sourceIdentifier": "I", "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0500000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "PART II", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500100-0000-4000-8000-000000000001", "structuralNodeId": "b0500100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "IMPORTANCE OF JAMAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500200-0000-4000-8000-000000000001", "structuralNodeId": "b0500100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "As has already been said in the foreword, there are many who say their salaat regularly but are not very particular about Jamaat. The Prophet (Sallallaho alaihe wasallam) is as emphatic in enjoining Jamaat as he is particular about salaat. This part also consists of two chapters. The first deals with the rewards of Jamaat and the second with the consequences of its neglect.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500300-0000-4000-8000-000000000001", "structuralNodeId": "b0500200-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500400-0000-4000-8000-000000000001", "structuralNodeId": "b0500300-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "REWARDS OF JAMAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500500-0000-4000-8000-000000000001", "structuralNodeId": "b0500400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500600-0000-4000-8000-000000000001", "structuralNodeId": "b0500400-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن عمر رضي الله عنه أن رسول الله ﷺ قال صلاة الجماعة أفضل من صلاة الفذ بسبع وعشرين درجة رواه مالك والبخاري ومسلم والترمذي كذا في الترغيب", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500700-0000-4000-8000-000000000001", "structuralNodeId": "b0500400-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Umar (Radhiyallaho anha) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"A salaat with Jamaat is twenty-seven times superior to salaat performed individually.\"\n\nWhen we offer our salaat for getting reward from Allah, then why should it not be done in the musjid, where the reward earned is twenty-seven times more. Nobody will be so unwise as to forego a profit twenty-seven times greater with simply a little extra labour. But we are so indifferent about the profits promised for our religious practices! This can be due to nothing but our disregard for deen and the rewards of it. It is a pity that we apply ourselves so hard to acquiring the trifling gains in this material world; but are so unmindful of the gains in the Hereafter, which yield twenty-seven times more with a little extra effort. We often argue that for going to the musjid for Jamaat we have to close the shop and will thus lose business. These pretexts and others of the kind cannot stand in the way of those who have perfect faith in the Greatness of Allah, and", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0510000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 51, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "51", "printedPageNumber": 51, "pdfPageNumber": 434, "sequenceIndex": 41, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0510100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0510000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "in His word; and who realize the value of the blessings and reward in the Hereafter. It is in respect of such people that Allah says:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رِجَالٌ لَا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَنْ ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Men, whom neither merchandise nor sale beguileth them from remembrance of Allah and constancy in ''salaat.''\" (XXIV: 37).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said of Saalim Haddaad (Rahmatullah alaih) (a trader and a great Soofi) that on hearing Azaan he would turn pale and grow restless. He would stand up immediately, leaving his shop open and recite these couplets:-\n\n1. \"When Thy summoner stands up to summon,\nquickly I stand up.\nTo respond to (the summons of) The Mighty Lord\nWho hath no peer.\"\n\n2. \"I reply to the summons with complete submission and cheer,\n''Here am I, O Bountiful One.''\"\n\n3. \"My face grows pale with awe and fear, and occupation in Thee distracts me from all other occupations.\"\n\n4. \"I swear by Thee, naught is dear to me save Thy remembrance.\nNothing is more ravishing for me than Thy sweet name.\"\n\n5. \"O, will there be a time for us to be together?\nA lover is happy only when he is with his love.\"\n\n6. \"He whose eyes have seen the light of Thy Beauty\nCan never be solaced. He must die yearning for Thee.\"\n\nIt is said in a hadith: \"People frequenting the musjid are its pegs (dwellers). Angels are their companions and visit them when they are sick and help them when they are at their jobs.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510500-0000-4000-8000-000000000001", "structuralNodeId": "b0510100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510600-0000-4000-8000-000000000001", "structuralNodeId": "b0510100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ صلاة الرجل في جماعة تضعف على صلاته في بيته وفي سوقه خمساً وعشرين ضعفاً وذلك أنه إذا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0520000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 52, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "52", "printedPageNumber": 52, "pdfPageNumber": 435, "sequenceIndex": 42, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0520000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}, {"id": "f0520100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "توضأ فأحسن الوضوء ثم خرج إلى المسجد لا يخرجه إلا الصلاة لم يخط خطوة إلا رفعت له بها درجة وحط عنه بها خطيئة فإذا صلى لم تزل الملائكة تصلي عليه ما دام في مصلاه اللهم صل عليه اللهم ارحمه ولا يزال في صلاة ما انتظر الصلاة", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}, {"id": "f0520200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Salaat with Jamaat is twenty-five times superior to salaat which is said in a house or in a shop. It is so because when a person performs wudhu in right earnest and walks on to the musjid, with the sole intention of performing salaat, each step he takes, adds one blessing to his account and wipes out one sin therefrom. Again, if he keeps sitting in the musjid (with wudhu of course) after the salaat is over, the angels keep on seeking Allah''s blessing and forgiveness for him. And as long as he keeps sitting in the musjid waiting for salaat; he goes on earning rewards as if he is busy in salaat.\"\n\nIn Hadith No. I, the superiority of salaat with Jamaat over that offered individually is described as being twenty-seven times more, while this hadith mentions only twenty-five times. Various theologians have discussed at length this seeming inconsistency. The following are some of the explanations:\n\n1. \"This variation from twenty-five to twenty-seven is due to variation of ikhlaas (sincerity) in different individuals.\"\n\n2. \"In Sirri (quiet) salaat (i.e., Zuhr and Asr), it is twenty-five times, while in Jahri (loud) salaat (i.e., Fajr, Maghrib and Ishaa), it is twenty-seven times.\"\n\n3. \"In Fajr and Ishaa, when it is somewhat inconvenient to go out due to cold and darkness, it is twenty-seven times, but in other salaats it is twenty-five times.\"\n\n4. \"In the beginning it was twenty-five times, but subsequently Allah (by special favour on the followers of the Prophet (Sallallaho alaihe wasallam)) raised the reward to twenty-seven times.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0530000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 53, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "53", "printedPageNumber": 53, "pdfPageNumber": 436, "sequenceIndex": 43, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0530000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 53"}, {"id": "f0530100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Some others have brought forward a still finer explanation. They say that the reward for salaat with Jamaat mentioned in this Hadith is not merely 25 times but a doubling (2 raised to the power) twenty-five times, which comes to 33,554,432 times. This is something not beyond the bountiful Mercy of Allah. When neglect of one salaat can cause punishment in Hell for one Huqb (as we have seen in the last chapter), so much reward for one salaat with Jamaat is quite conceivable.\n\nThe Prophet (Sallallaho alaihe wasallam) has also explained to us how the reward goes on increasing in the case of a person who, after performing wudhu, leaves his house with the sole intention of joining Jamaat for salaat in the musjid. Each step he takes, brings one reward as well as washes away one sin. Banu Salama, a clan in Madina, had their houses at some distance. They intended to shift close to the musjid. The Prophet (Sallallaho alaihe wasallam) however, advised them saying: \"Stay where you are. Every step you take when coming to musjid is written in your account.\" It is said in a hadith: \"The likeness of a person performing wudhu at home and then leaving for musjid is as the likeness of a person who, after dressing in the ihraam (Hajj apparel) at his house, leaves for Hajj.\"\n\nFurther, in the same hadith, the Prophet (Sallallaho alaihe wasallam) points to another act of great value; i.e., as long as one remains sitting in musjid after the salaat is over, the angels pray for him asking for forgiveness and mercy. The angels are the innocent and holy creation of Allah. So, the effectiveness of their prayers is self-evident.\n\nMuhammad bin Samaak (Rahmatullah alaih) is a famous theologian and Sheikh. He died at the age of one hundred and three. He used to perform two hundred rakaats of nafl salaat daily. He writes: \"For forty years, I never missed the first takbeer of salaat with Jamaat, except once when my mother had died.\" The same Shaikh writes: \"Once I missed the Jamaat. As I knew that salaat with Jamaat was twenty-five times superior, I repeated this salaat (individually) twenty-five times to make up the loss. I heard in my dream some one saying to me, ''Muhammad! You have repeated your salaat 25 times (in the hope of making good the loss), but what about the ''Aameen'' by the Angels?\" It is reported in many ahaadith that when the Imaam says ''Aameen'' after Fatihah, the Angels also say Aameen and all the past sins of a person whose Aameen coincides with that of the Angels are forgiven. This is", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 53"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0540000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 54, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "54", "printedPageNumber": 54, "pdfPageNumber": 437, "sequenceIndex": 44, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0540100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith III", "sourceIdentifier": "III", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0540000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}, {"id": "f0540100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "possible only in a salaat with jamaat, hence Maulana Abdul Hayy quoting this story about the Shaikh writes: \"Even if a person goes on repeating his salaat (individually) a thousand times, he cannot get the collective blessing of a salaat with Jamaat.\" This is obvious. He not only loses ''Aameen'' with the Angels, but also the blessings of the congregation and the prayers of the Angels after salaat, with many other spiritual benefits. This should also be borne in mind that the prayers of Angels can be deserved only when the salaat is a proper one. If the salaat of a person is not as it should be (according to hadith) it is flung back like a dirty rag at his face, then how can the Angels pray for him?", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}, {"id": "f0540200-0000-4000-8000-000000000001", "structuralNodeId": "b0540100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}, {"id": "f0540300-0000-4000-8000-000000000001", "structuralNodeId": "b0540100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن مسعود رضي الله عنه قال من سره أن يلقى الله غداً مسلماً فليحافظ على هؤلاء الصلوات حيث ينادى بهن فإن الله تعالى شرع لنبيكم ﷺ سنن الهدى وإنهن من سنن الهدى ولو أنكم صليتم في بيوتكم كما يصلي هذا المتخلف في بيته لتركتم سنة نبيكم ولو تركتم سنة نبيكم لضللتم وما من رجل يتطهر فيحسن الطهور ثم يعمد إلى مسجد من هذه المساجد إلا كتب الله له بكل خطوة يخطوها حسنة ويرفعه بها درجة ويحط عنه بها سيئة ولقد رأيتنا وما يتخلف عنها إلا منافق معلوم النفاق ولقد كان الرجل يؤتى به يهادى بين الرجلين حتى يقام في الصف وفي رواية ولقد رأيتنا وما يتخلف عن الصلاة إلا منافق قد علم نفاقه أو مريض إن كان الرجل ليمشي بين الرجلين حتى يأتي الصلاة وقال إن رسول الله ﷺ علمنا سنن الهدى وإن من سنن الهدى الصلاة في المسجد الذي يؤذن فيه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}, {"id": "f0540400-0000-4000-8000-000000000001", "structuralNodeId": "b0540100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Masood (Radhiyallaho anho) says: \"If one wishes to meet Allah on the Day of Judgement as a Muslim, he must say his salaat at a place where Azaan is called out, viz., a musjid, as Allah has prescribed through His Prophet (Sallallaho alaihe wasallam) such practices which are nothing but guidance through and through; and salaat (with Jamaat) is one of them. If you start saying your salaat at your houses (as so and so is doing), then you will be dis-", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 54"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0550000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 55, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "55", "printedPageNumber": 55, "pdfPageNumber": 438, "sequenceIndex": 45, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0550100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith IV", "sourceIdentifier": "IV", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0550000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "carding the Sunnah of the Prophet (Sallallaho alaihe wasallam) and no sooner you desert his Sunnah than you go astray. When a person performs wudhu correctly and then leaves for the musjid, at each step that he takes, he gets one blessing and has one sin wiped out. During the lifetime of the Prophet (Sallallaho alaihe wasallam) no one would miss Jamaat except an open munaafiq or a real invalid. Even the munaafiq dared not miss the Jamaat and a sick person who could be taken to the musjid with the help of two men would be helped to join Jamaat.\"\n\nThis shows the extreme vigilance of the Sahabah over their salaat with Jamaat. Even a sick person was brought to the musjid somehow or other, even though it needed two men to help him. This concern was quite natural when they found the Prophet (Sallallaho alaihe wasallam) himself so very particular about it. It is said that when the Prophet (Sallallaho alaihe wasallam) was on his deathbed, and he would frequently faint; he succeeded in making wudhu after several attempts and, though he could hardly stand, went to the musjid with the help of Hadhrat Abbas (Radhiyallaho anho) and another companion. Hadhrat Abu Bakr (Radhiyallaho anho) led the salaat at his instance, and he himself joined the Jamaat.\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates that the Prophet (Sallallaho alaihe wasallam) once said to him, \"Worship your Lord as if you see Him before you, count yourself among the dead, beware of the curse of the wronged ones and, even if you could crawl to the musjid, do not miss Ishaa and Fajr with Jamaat.\"\n\nIt is said in another hadith, \"Ishaa and Fajr are very heavy on those who are munaafiq. If they knew the reward of the Jamaat, they would go to the musjid and join the Jamaat even if they had to crawl.\"\n\n", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas bin Maalik (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550300-0000-4000-8000-000000000001", "structuralNodeId": "b0550100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550400-0000-4000-8000-000000000001", "structuralNodeId": "b0550100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أنس بن مالك رضي الله عنه قال قال رسول الله ﷺ من صلى لله أربعين يوماً في جماعة يدرك التكبيرة الأولى كتب له براءتان براءة من النار وبراءة من النفاق رواه الترمذي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0560000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 56, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "56", "printedPageNumber": 56, "pdfPageNumber": 439, "sequenceIndex": 46, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0560100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0560000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}, {"id": "f0560100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "saying, \"A person who in all sincerity is constant in his salaat with Jamaat for forty days, without missing the first takbeer, receives two awards: one for deliverance from Hell and the other for freedom from nifaaq.\"\n\nIf a person is regular in his salaat (with sincerity) for forty days and joins the Jamaat from the very start (i.e., when the Imaam calls out his first takbeer), then he shall neither be a munaafiq nor shall he go to Hell. A munaafiq is a person who feigns being a Muslim, but there is kufr in his heart. Genesis of man (according to hadith) takes place in periods of forty days. This seems to be the significance of forty days in this hadith, and so the Soofis attach importance to this period (called Chillah in Urdu) for purposes of spiritual discipline.\n\nLucky indeed are the persons who do not miss their first takbeer for years together.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}, {"id": "f0560200-0000-4000-8000-000000000001", "structuralNodeId": "b0560100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}, {"id": "f0560300-0000-4000-8000-000000000001", "structuralNodeId": "b0560100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ من توضأ فأحسن وضوءه ثم راح فوجد الناس قد صلوا أعطاه الله عز وجل مثل أجر من صلاها وحضرها لا ينقص ذلك من أجورهم شيئاً رواه أبو داود والنسائي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}, {"id": "f0560400-0000-4000-8000-000000000001", "structuralNodeId": "b0560100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"A person who performs wudhu scrupulously, and then goes to the musjid and finds that Jamaat is over, receives a reward equal to that of Jamaat. This would not diminish anything from the reward of those who have actually performed their salaat with Jamaat.\"\n\nThis is indeed Allah''s great favour and beneficence that the mere effort and a slight exertion is enough to entitle us to a reward of Jamaat, though actually we fail to join it. Who is the loser then if we ourselves get left, and miss the bounties of the most Bountiful?\n\nThis hadith also shows that we should not postpone going to the musjid in apprehension of the Jamaat being over. Even if we find on reaching the musjid that Jamaat is over, we will still get the reward thereof. If, however, we are certain that the Jamaat is already over, then there is of course no idea in going to the musjid for Jamaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 56"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0570000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 57, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "57", "printedPageNumber": 57, "pdfPageNumber": 440, "sequenceIndex": 47, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0570100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0570200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith VII", "sourceIdentifier": "VII", "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0570000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570100-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570200-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن قباث بن أشيم الليثي رضي الله عنه قال قال رسول الله ﷺ صلاة الرجلين يؤم أحدهما صاحبه أزكى عند الله من صلاة أربعة تترى وصلاة أربعة أزكى عند الله من صلاة ثمانية تترى وصلاة ثمانية يؤمهم أحدهم أزكى عند الله من صلاة مائة تترى رواه البزار والطبراني", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570300-0000-4000-8000-000000000001", "structuralNodeId": "b0570100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Qubaath bin Ashyam Allaithi (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Two persons performing salaat together with one as Imaam are liked by Allah more than four persons saying salaat individually. Similarly four persons performing salaat with Jamaat are liked by Allah more than eight persons saying it individually. Similarly again, eight persons performing salaat with Jamaat are liked by Allah more than one hundred persons saying it individually.\"\n\nIn another hadith it is said, \"A big Jamaat is more preferred by Allah than a small Jamaat.\" Some people think that there is no harm in having a small Jamaat of their own at their houses or at their business premises. This is not correct, as in the first place they are deprived of the reward of saying salaat in the musjid and secondly, they lose the blessing of salaat with a big Jamaat. The bigger the congregation, the more pleasing it is to Allah. When our sole aim is to achieve the pleasure of Allah, why should we not adopt a manner more pleasing to Him. It is reported in a hadith that Allah is pleased to see three things, namely, a row of worshippers offering salaat with Jamaat, a person busy in salaat at the time of Tahajjud at the dead of night, and a person fighting in the way of Allah.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570400-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570500-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن سهل بن سعد الساعدي رضي الله عنه قال قال رسول الله ﷺ بشر المشائين في الظلم إلى المساجد بالنور التام يوم القيامة رواه ابن ماجه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}, {"id": "f0570600-0000-4000-8000-000000000001", "structuralNodeId": "b0570200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Sahl bin Sa''d (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Give glad tidings to those who go to the musjid frequently during hours of darkness, for they will have perfect light on the Day of Judgement.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 57"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0580000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 58, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "58", "printedPageNumber": 58, "pdfPageNumber": 441, "sequenceIndex": 48, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0580000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}, {"id": "f0580100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The value of going to the musjid in the darkness of night shall be realised on the dreadful Day of Judgement, when everybody shall be in a very miserable plight. A person subjecting himself to inconvenience in the hours of darkness in this world shall be more than compensated in the next, as he shall carry with him a light more glorious than that of the sun. In a hadith it is reported that such persons shall occupy the pulpits of light, with no worry at all, while others will be in utter bewilderment. In another hadith it is said, \"Allah will say on the Day of Judgement, Where are My neighbours?\" The Angels will inquire, \"Who are Thy neighbours, O Allah?\" Allah will reply, \"Those who used to frequent the mosques.\"\n\nIn a hadith it is said, \"Of all the places on this Earth, the mosques are the dearest to Allah, and the markets are the most offensive to Him.\"\n\nIn another hadith, the ''masaajid'' are called \"The gardens of Paradise.\"\n\nHadhrat Abu Sa''eed (Radhiyallaho anho) narrates, \"The Prophet (Sallallaho alaihe wasallam) once said, ''Bear testimony to the Imaan of the person frequenting the musjid,'' and then he recited the following verse of the Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}, {"id": "f0580200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}, {"id": "f0580300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"He only shall tend Allah''s musjid who believes in Allah and the Last Day.\" (IV: 18).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}, {"id": "f0580400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The following are a few more ahaadith about the virtues of salaat with Jamaat:-\n\n1. \"Making wudhu when inconvenient, walking towards the musjid and sitting there (after one salaat), waiting for the next salaat, wipe out the sins.\"\n\n2. \"The farther a person lives from the ''musjid'' the greater the blessing he receives.\" This is so because a person coming from a distance shall have to walk more and, as already mentioned, every step will fetch him a blessing. For this very reason some companions have been reported to be taking short steps in going to the musjid in order to earn more blessings.\n\n3. \"There are three things in this world for which", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 58"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0590000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 59, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "59", "printedPageNumber": 59, "pdfPageNumber": 442, "sequenceIndex": 49, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0590000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 59"}, {"id": "f0590100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "people would fight with one another if they come to know their rewards. These are: To call out the Azaan; to go to the musjid for Zuhr in the scorching heat of the sun; and to be in the first line while in salaat with Jamaat.\"\n\n4. \"Seven persons shall be accommodated under the shade of Allah''s mercy on the Day of Judgement, when everybody will be most bewildered under the inconceivably intense heat of the sun. One of them will be the person whose heart remains attached to the musjid. He is anxious to return to the musjid if he leaves it on any account. Another hadith narrates that Allah loves those who love the musjid.\"\n\nEach article of faith in Islam is a source of innumerable blessings and rewards from Allah, and carries boundless benefits showered on those who adhere to it. Besides, no commandment of Allah is without a deep significance. It is often difficult to understand the full benefits of Allah''s commandments; as no one can encompass His Knowledge and Wisdom. Some of the sages of Islam have tried to explain the importance of salaat with Jamaat, but their explanations vary with the extent of their understanding and their power to probe into Divine secrets. Our respected Shaikh, Shah Waliullah Dehlawi (may Allah illumine his grave), in his famous Book ''Hujjatullahil Balighah'' writes:-\n\n\"To save the people from the fatal effects that their own customs and rituals can bring them, there is nothing more useful than to make one of the religious services so common a custom and so public a ritual that it may be performed openly before everybody by any person, whether he be learned or illiterate. The town-folk and the countrymen should both be equally anxious to observe it. It should become a subject of rivalry and pride among all of them, and it should be so universally practised that it becomes part and parcel of their social set-up, so much so, that life without it may be worthless for them. If this is achieved, it will help in establishing the worship and obedience of Allah and will form a very useful substitute for those rituals and customs which could cause them serious harm. Since salaat is the only religious observance that surpasses all others in importance and universality, both in reason and authority, it becomes therefore absolutely necessary to", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 59"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0600000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 60, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "60", "printedPageNumber": 60, "pdfPageNumber": 443, "sequenceIndex": 50, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0600000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 60"}, {"id": "f0600100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "get it established universally by propagating it and by arranging special congregations, where it can be performed with absolute uniformity of form and purpose.\"\n\n\"Further, in every community or religious society, there are a few who have the capacity to lead, while the rest simply follow. There are some others who can be corrected with a little counsel or reproach. Then there is a third grade of people who are very weak in faith and, if they are not made to worship in public, they are prone to discard it altogether. It is therefore in the best interests of the Islamic society that all its members perform the worship collectively and in congregation, so that the delinquents may be distinguished from the observers and the shirkers from the adherents. This will also cause the people with less knowledge to follow the Ulama, and make the ignorant to learn from the learned the specific requirements of worship. The worshipper will distinguish right from wrong and genuine from counterfeit, so that the right and the genuine may prevail and the wrong and the counterfeit may be suppressed.\"\n\n\"Besides, these congregations of people loving Allah, seeking His Mercy, constantly fearing Him and having their hearts and souls turned to Him alone, have the wonderful effect of causing His blessings and Mercy to descend from Heaven.\n\n\"Moreover, the Muslim community has been raised so that the word of Allah be held supreme and Islamic Order be paramount over all others. This object cannot be achieved unless all Muslims, big and small, the elite and the common, the town folk and the countrymen, perform alike the most sublime service and the most sacred ritual of Islam (i.e., salaat) by assembling together in one place. It is for this reason that the Sharee-at (Islamic Law) lays such special stress on Friday congregation and on salaat with jamaat, by explaining the blessings that accrue therefrom and punishments awarded for neglect thereof. For the open and conspicuous observance of this important service, two types of assemblies are required; one for people of a clan or a particular locality and the other for the people of the whole town. Since the assembly of the former at any hour is convenient and that of the latter comparatively difficult, so for the former the gathering for salaat (with jamaat) five times daily, has been laid down and in the case of the latter gathering, the weekly Friday salaat has been devised and ordained.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 60"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0610000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 61, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "61", "printedPageNumber": 61, "pdfPageNumber": 444, "sequenceIndex": 51, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0610100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "REPROACH ON GIVING UP JAMAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0610200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith I", "sourceIdentifier": "I", "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0610000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER II", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610100-0000-4000-8000-000000000001", "structuralNodeId": "b0610100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "REPROACH ON GIVING UP JAMAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610200-0000-4000-8000-000000000001", "structuralNodeId": "b0610100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Just as Allah has promised rewards and blessings for adhering to His commandments, so has He warned us of the woeful consequences and punishments for their neglect. We are in bondage to Allah and as such it is obligatory on us to obey Him. No compensation or reward is due to us for our obedience to Him. If He gives a reward, it is surely a matter of His extreme favour on us. Similarly no punishments can be too much for us if we disobey Him—our Lord, for there can be no greater crime for a bondsman than to disobey his Master. Hence no warning or premonition was required to be imparted. Yet Allah and His Holy Prophet (Sallallaho alaihe wasallam) have so very kindly cautioned us in various ways, warned us frequently of the consequences and explained to us again and again, just to save us from disaster. If even then, we don''t take a lesson, who could there be to save us from the inevitable consequences?", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610300-0000-4000-8000-000000000001", "structuralNodeId": "b0610200-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610400-0000-4000-8000-000000000001", "structuralNodeId": "b0610200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن عباس رضي الله عنه قال قال رسول الله ﷺ من سمع النداء فلم يمنعه من اتباعه عذر قالوا وما العذر قال خوف أو مرض لم تقبل منه الصلاة التي صلى رواه أبو داود وابن حبان في صحيحه وابن ماجه نحوه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610500-0000-4000-8000-000000000001", "structuralNodeId": "b0610200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Ibn Abbas (Radhiyallaho anho) narrates, \"I heard the Prophet (Sallallaho alaihe wasallam) saying, ''If a person in spite of hearing the Azaan does not go to the musjid (and he prefers to say his salaat at home) without a strong excuse, then his salaat is not accepted.'' When the Companions inquired as to what could be a strong excuse, he replied, ''Illness or fear.''\"\n\nIt may perhaps appear from this Hadith that the salaat performed at home (after hearing the Azaan) is no salaat at all; the Hanafiyyah do not hold this view. According to them, though the reward and blessings promised for fardh salaat will not be awarded, yet the person saying the salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0620000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 62, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "62", "printedPageNumber": 62, "pdfPageNumber": 445, "sequenceIndex": 52, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0620100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0620000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "at his place does absolve himself of the obligation. But in the opinion of some of the companions and their successors, salaat with jamaat (after hearing the Azaan) is fardh and its discard is haraam. According to many other theologians, such a person is not even absolved of the obligation in respect of salaat of that hour. Anyhow, he is surely committing the sin of discarding jamaat. In another hadith narrated by Hadhrat Ibn Abbas, it is stated that such a person is guilty of disobedience of Allah and His Apostle (Sallallaho alaihe wasallam). Hadhrat Ibn Abbas (Radhiyallaho anho) also says, \"No good is done by, nor any good is done to, the person who does not join jamaat after hearing the Azaan.\" Hadhrat Abu Hurairah (Radhiyallaho anho) says, \"It is more appropriate to pour molten-lead into the ears of a person who does not go to join jamaat.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620200-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620300-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "قال العلماء كل من سمع النداء فلم يجب فلا صلاة له وقال ﷺ بحسب المؤمن من الشقاء والخيبة أن يسمع المؤذن يثوب بالصلاة فلا يجيبه رواه الطبراني عن معاذ بن أنس كذا في الكنز", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620400-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Mu''aaz bin Anas (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"A person who does not go for salaat after hearing the Azaan is committing a great wrong and is doing an act of kufr and nifaaq.\"\n\nAccording to this hadith, not to join jamaat after hearing the Azaan is not becoming of a Muslim and is the practice of a kaafir or a munaafiq. What a strong reproof!\n\nIn another hadith, it is said, \"Not to join jamaat after hearing the Azaan is sufficient to render a person most unfortunate and most wretched.\"\n\nHadhrat Sulaimaan bin Abi Hathmah (Radhiyallaho anho) is one of the eminent people of the early days of Islam. He was born during the lifetime of the Prophet (Sallallaho alaihe wasallam), but was too young then to have had the honour of listening to any hadith from him. During the Caliphate of Hadhrat Umar (Radhiyallaho anho) he was made in charge of the market. One day Hadhrat Umar (Radhiyallaho anho) found him missing in Fajr salaat. Hadhrat Umar (Radhiyallaho anho) went to his house and inquired from his mother why Sulaimaan was not present in Fajr. She replied, \"He kept saying nafl salaat throughout the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0630000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 63, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "63", "printedPageNumber": 63, "pdfPageNumber": 446, "sequenceIndex": 53, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0630100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith III", "sourceIdentifier": "III", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0630000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (b)—Reproach on Discard of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "night, and sleep overpowered him at the time of Fajr.\" At this, Hadhrat Umar (Radhiyallaho anho) remarked, \"I would prefer my Fajr with jamaat to my offering nafl salaat all night long.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630200-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630300-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ لقد هممت أن آمر فتيتي فيجمعوا حزماً من حطب ثم آتي قوماً يصلون في بيوتهم ليست بهم علة فأحرقها عليهم رواه أبو داود وابن ماجه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630400-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"I wish I could ask the boys to collect a huge quantity of firewood for me, and then, I would go around and set fire to the dwellings of those who say their salaat at their own houses without any excuse.\"\n\nThe Prophet (Sallallaho alaihe wasallam), who was most kind and merciful towards his followers and was greatly pained to see them even in a little trouble, gets offended so much that he is ready to set fire to the houses of those who are content with saying salaat at their houses.\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"If there are (even) three persons in a village or in a desert, and they do not say their salaat with jamaat, then Satan gets hold of them. Remember that jamaat for salaat is very necessary for you. Surely a wolf devours a lonely sheep, and Satan is the wolf for men.\"\n\nThis shows that people busy in farming etc. should arrange to say their salaat with jamaat if they are three or more in number. Even if they are two, it is better to have", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0640000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 64, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "64", "printedPageNumber": 64, "pdfPageNumber": 447, "sequenceIndex": 54, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0640100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0640000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "jamaat. The farmers in our country are generally negligent of salaat and consider their occupation a sufficient excuse for their neglect, and even those who are considered pious prefer to perform their salaat individually. If the farmers working in the nearby fields get together at a place and perform prayers in jamaat, they can have quite a big gathering and thereby receive the wonderful blessings of Allah. Notwithstanding the sun, rain, heat and cold, they keep busy for a trifling worldly gain, but lose tremendous amount of Allah''s reward by losing salaat. On the other hand, they can earn a reward fifty times more (as conveyed in another hadith) by offering their salaat with jamaat in the fields.\n\nIt is stated in a hadith, \"When a shepherd calls out the Azaan at the foot of a hill (or in the fields) and starts his salaat, Allah is greatly pleased with him and says proudly to the Angels, ''Behold My slave! He has called out the Azaan and is offering his salaat. All this he does out of fear for Me. I therefore grant him forgiveness and declare his admittance into Paradise.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640200-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640300-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن عباس رضي الله عنهما أنه سئل عن رجل يصوم النهار ويقوم الليل ولا يشهد الجمعة ولا الجماعة قال هو في النار رواه الترمذي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640400-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Somebody asked Ibn Abbas (Radhiyallaho anho), \"What about a person who keeps fast all day and offers nafl salaat all night, but does not go to the musjid for jamaat and Jumu''ah?\" \"He is doomed to Hell\", replied Hadhrat Ibn Abbas (Radhiyallaho anho).\n\nSuch a person, being a Muslim, may ultimately get freedom from Hell, but who knows after how long. The ignorant among the Soofis and Shaikhs are very particular about Zikr and nafl salaat and consider this an act of eminence in piety, while they are not particular about salaat with jamaat. It must be clearly borne in mind for all times that no person can achieve religious eminence except through complete adherence to the practices of the beloved Prophet (Sallallaho alaihe wasallam).\n\nIt is stated in a hadith that Allah curses three persons: An Imaam who insists on leading the people of a place in salaat, although they do not like him on some reasonable account, a woman who is under the displeasure of her hus-", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0650000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 65, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "65", "printedPageNumber": 65, "pdfPageNumber": 448, "sequenceIndex": 55, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0650100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0650000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (b)—Reproach on Discard of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "band; and a person who hears the Azaan but does not go to the musjid for salaat with Jamaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650200-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650300-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أخرج ابن مردويه عن كعب الحبر قال والذي أنزل التوراة على موسى والإنجيل على عيسى والزبور على داود والفرقان على محمد أنزلت هذه الآيات في الصلوات المكتوبات حيث ينادى بهن يوم يكشف عن ساق إلى قوله وهم سالمون، الصلوات الخمس إذا نودي بها وأخرج البيهقي في الشعب عن سعيد بن جبير قال الصلوات في الجماعات وأخرج البيهقي عن ابن عباس قال رجل يسمع الأذان فلا يجيب الصلاة كذا في الدر المنثور قلت وقام الآية يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون خاشعة أبصارهم ترهقهم ذلة وقد كانوا يدعون إلى السجود وهم سالمون", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650400-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Ka''b Ahbaar says, \"By Him who revealed the Torah to Moosa, the Injeel to Eesa, the Psalms to Dawood (Alayhimus salaam), and the Qur''an on Muhammad (Sallallaho alaihe wasallam), the following verses were revealed in respect of saying fardh salaat in those places (mosques) where the Azaan is said: \"On the day when the glory of Saaq is revealed and they are ordered to prostrate themselves, but are not able, with eyes downcast, abasement stupifying them. And they had been summoned to prostrate themselves when they were quite hale and healthy.\" (LXVIII: 42 and 43).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650500-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The glory of Saaq is a particular type of glory to be displayed on the Day of Judgement. All Muslims will fall prostrate on seeing this glory, but there will be some whose backs will turn stiff and they will be unable to prostrate themselves. As to who these unlucky persons would be, different interpretations have been given by different commentators. According to this hadith, which is also corroborated by another narrated by Hadhrat Ibn Abbas (Radhiyallaho anho), those shall be the persons who were called for salaat with jamaat, but did not go for it.\n\nA few other interpretations of the same are given below:—\n\n1. Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates on the authority of the Prophet (Sallallaho alaihe wasallam) that these shall be the persons who used to offer their salaat to be seen by other men.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0660000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 66, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "66", "printedPageNumber": 66, "pdfPageNumber": 449, "sequenceIndex": 56, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0660000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 66"}, {"id": "f0660100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "2. These shall be infidels who did not say salaat at all;\n\n3. These shall be the munaafiqeen. (Allah knows best and His knowledge is most perfect).\n\nWhat a terrible thing to be so abased and disgraced on the Day of Judgement that, while all Muslims shall fall prostrate at seeing Allah''s glory, those who neglected salaat with jamaat shall be singled out by their inability to do so.\n\nBesides these, many other warnings have been given against the neglect of jamaat. But as a matter of fact, none is necessary for a good Muslim to whom the word of Allah and His Apostle (Sallallaho alaihe wasallam) is all important. And for one who has no regard for their word, all such warnings are meaningless. But a time will come when every soul shall be called to account, and punished for its misdeeds, and then no amount of penitence shall be of any avail.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 66"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0670000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 67, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "67", "printedPageNumber": 67, "pdfPageNumber": 450, "sequenceIndex": 57, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0670100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "IMPORTANCE OF SINCERITY AND DEVOTION IN SALAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0670200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER I", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0670300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "QUOTATIONS FROM THE QUR''AN", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0670400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—I", "sourceIdentifier": null, "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0670000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "PART III", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670100-0000-4000-8000-000000000001", "structuralNodeId": "b0670100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "IMPORTANCE OF SINCERITY AND DEVOTION IN SALAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670200-0000-4000-8000-000000000001", "structuralNodeId": "b0670100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "There are many persons who offer their salaat and quite a lot of them are particular about jamaat as well, but they say it so imperfectly that, instead of earning blessings and reward for them, it is rejected forthwith. This, however, is not so bad as to discard salaat altogether, which as we have already learnt, is very serious. Although we are deprived of the rewards by saying a defective salaat, which is not accepted, yet we are saved from the insolence of neglecting and disobeying Allah''s commandments. However, when we spend our time, leave our work and undergo inconvenience, then why should we not see that we get the best return for our time and labour by saying our salaat as best as we can?\n\nThis third part is divided into three chapters. In the first chapter, a few quotations from the Holy Qur''an about the people who are condemned for their bad salaat and those who are praised for their good salaat, are given. In the second Chapter, stories about the salaat of a few lovers of Allah are collected. The third chapter consists of the sayings of the Prophet (Sallallaho alaihe wasallam) on this subject.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670300-0000-4000-8000-000000000001", "structuralNodeId": "b0670200-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670400-0000-4000-8000-000000000001", "structuralNodeId": "b0670300-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "QUOTATIONS FROM THE QUR''AN", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670500-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670600-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "لَنْ يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا وَلَٰكِنْ يَنَالُهُ التَّقْوَىٰ مِنْكُمْ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670700-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Their flesh and their blood reach not Allah, but devotion from you reacheth to Him.\" (XXII: 37)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670800-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Although this particular verse refers to the animal sacrifice, yet in principle it equally applies to all other rituals. It is sincerity and devotion in a service by which its acceptance would be judged by Allah. Hadhrat Mu''aaz (Radhiyallaho", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0680000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 68, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "68", "printedPageNumber": 68, "pdfPageNumber": 451, "sequenceIndex": 58, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0680100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—II", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0680200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—III", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0680300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—IV", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0680000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "anho) says, \"When the Prophet (Sallallaho alaihe wasallam) deputed me to Yemen, I requested him to give me some parting advice. He replied, ''Be sincere in all your services, as sincerity will magnify the value of an action, however insignificant it may be.''\"\n\nHadhrat Thaubaan (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Blessed be the sincere ones, for they are the lamps of guidance. They cause the worst evils to be driven off through their sincerity.\" It is said in another hadith, \"It is through the presence of the weak and due to their salaat and their sincerity that Allah''s help comes to all the people.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680200-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680300-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680400-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Woe unto worshippers who are heedless of their salaat, who want but to be seen at salaat.\" (CVII: 4–6)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680500-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "\"To be heedless\" has been given the following different interpretations:\n\n1. To be so careless as to miss the correct time of salaat.\n2. To be inattentive in salaat.\n3. To forget the number of rakaats.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680600-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680700-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَىٰ يُرَاءُونَ النَّاسَ وَلَا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680800-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"When they (the hypocrites) stand up for salaat, they perform it without earnestness and want but to be seen by men and are mindful of Allah but little.\" (IV: 142)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680900-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0681000-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلَاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0681100-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Now there hath succeeded them (Prophets) a later generation who have ruined salaat and have followed lusts. So they will meet Ghayy.\" (XIX: 59)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0690000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 69, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "69", "printedPageNumber": 69, "pdfPageNumber": 452, "sequenceIndex": 59, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0690100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—V", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0690200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—VI", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0690000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "In the dictionary ''Ghayy,'' is explained as deception, which points towards the awful doom and ruin in the hereafter. According to many commentators, Ghayy is a pit in Hell full of blood and pus. The persons who had ruined their salaat shall be thrown into this pit.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690200-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690300-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَمَا مَنَعَهُمْ أَنْ تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ إِلَّا أَنَّهُمْ كَفَرُوا بِاللَّهِ وَبِرَسُولِهِ وَلَا يَأْتُونَ الصَّلَاةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنْفِقُونَ إِلَّا وَهُمْ كَارِهُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690400-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And naught preventeth that their (the hypocrites) contributions should be accepted from them, save that they have disbelieved in Allah and in His Apostle, and they come not to worship, save as idlers, and pay not (their contribution) save reluctantly.\" (IV: 54)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690500-0000-4000-8000-000000000001", "structuralNodeId": "b0690100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Note: The quotations I to V above relate to those who ruin salaat. On the other hand, the following speak of those whom Allah praises for their good salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690600-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690700-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ ۝ وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ ۝ وَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ ۝ وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَىٰ أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَىٰ وَرَاءَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْعَادُونَ ۝ وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ ۝ وَالَّذِينَ هُمْ عَلَىٰ صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُولَٰئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690800-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Successful indeed are the believers who are humble in their salaat. And who shun vain conversation. And who are payers of the Zakaat. And who abstain from sex, save from their wives or the slaves that their right hand possess, for then they are not blameworthy but who craveth beyond that, such are transgressors—And who faithfully observe their pledges and their covenants. And who pay heed to their salaat. These are the heirs who will inherit Firdaus (Paradise). There they will abide.\" (XXIII: 1 to 11)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}, {"id": "f0690900-0000-4000-8000-000000000001", "structuralNodeId": "b0690200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Prophet (Sallallaho alaihe wasallam) says, \"Firdaus is the apex and the best portion of Paradise, where", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 69"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0700000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 70, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "70", "printedPageNumber": 70, "pdfPageNumber": 453, "sequenceIndex": 60, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0700100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—VII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0700200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—VIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0700000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "from all its rivers originate. Allah''s throne will be placed there. When you pray for Paradise, always pray for Firdaus.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700200-0000-4000-8000-000000000001", "structuralNodeId": "b0700100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700300-0000-4000-8000-000000000001", "structuralNodeId": "b0700100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ ۝ الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلَاقُو رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَاجِعُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700400-0000-4000-8000-000000000001", "structuralNodeId": "b0700100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And truly it (salaat) is hard save for the humble-minded; who know that they have to meet their Lord, and that unto Him they are returning.\" (II: 45–46)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700500-0000-4000-8000-000000000001", "structuralNodeId": "b0700200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—VIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700600-0000-4000-8000-000000000001", "structuralNodeId": "b0700200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ يُسَبِّحُ لَهُ فِيهَا بِالْغُدُوِّ وَالْآصَالِ ۝ رِجَالٌ لَا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَنْ ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ الْقُلُوبُ وَالْأَبْصَارُ ۝ لِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا عَمِلُوا وَيَزِيدَهُمْ مِنْ فَضْلِهِ وَاللَّهُ يَرْزُقُ مَنْ يَشَاءُ بِغَيْرِ حِسَابٍ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700700-0000-4000-8000-000000000001", "structuralNodeId": "b0700200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"In houses which Allah hath allowed to be exalted, and His name shall be remembered therein, do offer praise to Him at morning and evening, men whom neither merchandise nor sale beguileth from remembrance of Allah and establishment of salaat and paying Zakaat, who fear that Day when the hearts and the eyeballs will be over-turned so that Allah may reward them for the best of what they did and increase reward for them out of His bounty. Allah giveth blessings without measure to whom He will.\" (XXIV: 36 to 38)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}, {"id": "f0700800-0000-4000-8000-000000000001", "structuralNodeId": "b0700200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Abbas (Radhiyallaho anho) says, \"Establishment of salaat means performance of ruku and sajdah, properly and constant concentration in salaat with complete humility and submission.\" Hadhrat Qataadah (Radhiyallaho anho) says: \"Wherever the words ''Establishment of salaat'' occur in Qur''an, they mean to guard its hours, to perform wudhu in the right manner and to observe ruku and sajdah properly.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 70"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0710000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 71, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "71", "printedPageNumber": 71, "pdfPageNumber": 454, "sequenceIndex": 61, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0710100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—IX", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0710200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—X", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0710300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XI", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0710000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710100-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—IX", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710200-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَامًا ۝ وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710300-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"The (faithful) slaves of Rahmaan (the Beneficent) are they who walk upon the earth modestly and when the foolish ever address them, they answer: Peace; and who spend the night before their Lord, prostrate and standing.\" (XXV: 63–64)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710400-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "After describing a few more qualities of His faithful slaves, Allah says in the same context:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710500-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أُولَٰئِكَ يُجْزَوْنَ الْغُرْفَةَ بِمَا صَبَرُوا وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَامًا ۝ خَالِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710600-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"They will be awarded the high place for as much as they were steadfast, and they will meet therein with welcome and the word of peace. Abiding there for ever. Happy is it as abode and station.\" (XXV: 75–76)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710700-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—X", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710800-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "تَتَجَافَىٰ جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ ۝ فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710900-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"The believers in our revelations are those who forsake their beds, to cry unto their Lord in fear and hope, and spend of what We have bestowed on them. No soul knoweth what is kept hid for them of joy, as a reward for what they used to do.\" (XXXII: 16–17)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711000-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711100-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ ۝ آخِذِينَ مَا آتَاهُمْ رَبُّهُمْ إِنَّهُمْ كَانُوا قَبْلَ ذَٰلِكَ مُحْسِنِينَ ۝ كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711200-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 12, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! those who keep from evil will dwell amid gardens and water-springs, taking to that which their Lord", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0720000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 72, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "72", "printedPageNumber": 72, "pdfPageNumber": 455, "sequenceIndex": 62, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0720100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0720200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0720000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "giveth them; for Lo! aforetime they were doers of good. They used to sleep but little in the night. And ere the dawning of each day, would seek forgiveness.\" (LI: 15–18)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720200-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720300-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أَمَّنْ هُوَ قَانِتٌ آنَاءَ اللَّيْلِ سَاجِدًا وَقَائِمًا يَحْذَرُ الْآخِرَةَ وَيَرْجُو رَحْمَةَ رَبِّهِ قُلْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُولُو الْأَلْبَابِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720400-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Is he who worships devoutly in the hours of the night, prostrate or standing, afraid of the Hereafter and hoping for the mercy of his Lord (to be counted equal with a disbeliever)? Say (unto them, O Muhammad) (Sallallaho alaihe wasallam): \"Can those who know be equal with those who know not? But only men of understanding will pay heed.\" (XXXIX: 9)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720500-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720600-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَالْمَلَائِكَةُ يَدْخُلُونَ عَلَيْهِمْ مِنْ كُلِّ بَابٍ ۝ سَلَامٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720700-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "And angels would be entering through every door proclaiming: \"Peace be upon you, as a reward for your perseverance on religious practices.\" Thus how splendid would be their end! (XIII: 22–23).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720800-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الْإِنْسَانَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا ۝ إِلَّا الْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَائِمُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720900-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! man was created very impatient. Fretful when evil befalleth him. And niggardly when good befalleth him, save the worshippers who are constant at their salaat.\" (LXX: 19–23)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0721000-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "After giving some more qualities of these blessed people, Allah says in the same context:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0721100-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَالَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ ۝ أُولَٰئِكَ فِي جَنَّاتٍ مُكْرَمُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0730000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 73, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "73", "printedPageNumber": 73, "pdfPageNumber": 456, "sequenceIndex": 63, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0730000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And those who guard their salaat. These will dwell in gardens, honoured.\" (LXX: 34–35).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Besides the quotations given above, there are many verses of the Holy Qur''an enjoining salaat and exalting and extolling those who say their salaat properly. Salaat is indeed a great boon. That is why Muhammad (Sallallaho alaihe wasallam) has called it ''the comfort of my eyes'', and Ibrahim (Alayhis salaam) prayed to Allah,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"My Lord! make me to establish Salaat, and some of my posterity (also); our Lord! and accept the prayer.\" (XIV: 40)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Here the eminent Prophet of Allah, whom Allah has called ''Khaleel'', is asking Allah to make him say his salaat properly and regularly. The Glorious Allah Himself is ordering His beloved Prophet (Sallallaho alaihe wasallam) thus:—", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَىٰ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And enjoin salaat upon the people and be constant therein. We ask not of thee a provision. We provide for thee. And the Hereafter is for righteousness.\" (XX: 132).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730800-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said in a hadith that whenever the housefolk of the Prophet (Sallallaho alaihe wasallam) were hard-pressed in any way, he enjoined salaat on them and used to recite this verse. All the Prophets of Allah (peace be upon them) are reported to have engaged themselves in salaat whenever they had any difficulty. But, alas! we are so unmindful and indifferent about salaat that, in spite of all that we proclaim about Islaam and Islamic practices, we pay no attention to it. But on the contrary, if anybody stands up to invite us and to draw our attention towards it, we cut jokes and sneer at him and oppose him, thereby harming none else but ourselves.\n\nEven those who offer the salaat, often perform it in such a way that it will not be wrong to call it a mockery of salaat, as it lacks the proper observation of its requisites", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0740000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 74, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "74", "printedPageNumber": 74, "pdfPageNumber": 457, "sequenceIndex": 64, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0740000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 74"}, {"id": "f0740100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "and also the devotion and submission obligatory therein. The practical example of the Holy Prophet (Sallallaho alaihe wasallam), as also the practices of his illustrious companions, should be the guiding factor in our lives. I have collected the stories about the salaat of the companions in a separate book, named \"Stories of Sahabah\"; and I need not repeat them here. However, I am giving stories from the lives of a few pious persons in the following pages. The practices and the sayings of the Holy Prophet (Sallallaho alaihe wasallam) about this subject would appear in Chapter III.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 74"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0750000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 75, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "75", "printedPageNumber": 75, "pdfPageNumber": 458, "sequenceIndex": 65, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0750100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER II", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0750200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "A FEW STORIES FROM THE LIVES OF THE PIOUS", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0750300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—I", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0750400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—II", "sourceIdentifier": null, "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}, {"id": "b0750500-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—III", "sourceIdentifier": null, "title": null, "sequenceIndex": 4, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0750000-0000-4000-8000-000000000001", "structuralNodeId": "b0750100-0000-4000-8000-000000000001", "sequenceIndex": 0, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750100-0000-4000-8000-000000000001", "structuralNodeId": "b0750200-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "A FEW STORIES FROM THE LIVES OF THE PIOUS", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750200-0000-4000-8000-000000000001", "structuralNodeId": "b0750300-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750300-0000-4000-8000-000000000001", "structuralNodeId": "b0750300-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Shaikh Abdul Waahid (Rahmatullah alaih) says, \"One day I was so much overpowered by sleep that I went to bed before finishing my Zikr for the night. I saw in my dream a most beautiful girl dressed in green silk. All parts of her body and even her shoes were engaged in Zikr. She said to me ''Aspire to possess me; I love you.'' And then she recited a few couplets depicting the eagerness of a lover. When I woke up from the dream, I vowed not to sleep any more during the night. It is reported that for full forty years he never slept at night, and said Ishaa and Fajr salaats with the same wudhu.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750400-0000-4000-8000-000000000001", "structuralNodeId": "b0750400-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750500-0000-4000-8000-000000000001", "structuralNodeId": "b0750400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Shaikh Mazhar Sa''di (Rahmatullah alaih), the famous pious man, kept weeping for sixty years in love and eagerness for Allah. One night he saw in a dream a few damsels by the side of pearl trees with gold branches, on the bank of the brook brimming with fluid musk, pure and fragrant. The girls were hymning the glory of Allah. He asked their identity. In reply they recited two couplets, which meant, \"We have been created by the Sustainer of mankind and Lord of Muhammad (Sallallaho alaihe wasallam) for those people who keep standing before Allah all night long and hymning in supplication to Him.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750600-0000-4000-8000-000000000001", "structuralNodeId": "b0750500-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750700-0000-4000-8000-000000000001", "structuralNodeId": "b0750500-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Abu Bakr Dharir (Rahmatullah alaih) says, \"There lived a young slave with me. He fasted all day and stood in Tahajjud all night long. One day he came to me and related: ''Last night against my usual practice I went to sleep. I saw in my dream that the wall of the Mihraab was cracked, and from the crevice appeared a few damsels. One of them was very ugly. I asked one of the pretty damsels", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0760000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 76, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "76", "printedPageNumber": 76, "pdfPageNumber": 459, "sequenceIndex": 66, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0760100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—IV", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0760200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—V", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0760300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—VI", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0760000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "who they were. She replied that they were my previous nights and that the ugly one was this night.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760200-0000-4000-8000-000000000001", "structuralNodeId": "b0760100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760300-0000-4000-8000-000000000001", "structuralNodeId": "b0760100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "An eminent Shaikh says: \"One night I was in a deep sleep and could not get up for Tahajjud. I saw in my dream a girl of such beauty as I had never seen in my life. She was emitting such fragrance as I had never smelt before. She handed over to me a piece of paper on which were written three couplets, which meant, ''You were so enamoured of deep sleep that you have become unmindful of the high balconies of Paradise, where you have to abide for ever with no fear of death. Wake up! It is better to recite the Qur''an in Tahajjud, than to sleep.'' Since then, wherever I feel sleepy, these couplets come to my mind and the sleep goes away.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760400-0000-4000-8000-000000000001", "structuralNodeId": "b0760200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760500-0000-4000-8000-000000000001", "structuralNodeId": "b0760200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Ataa (Rahmatullah alaih) writes, \"I went to the market. A person had a slave girl to sell, who was said to be mad; I purchased her for seven dinaars and brought her to my house. After a portion of the night had passed, I noticed that she got up, performed wudhu and started her salaat. In her salaat she wept so much that I thought she would die of excessive crying. After finishing the salaat, she began to supplicate before Allah saying, ''O my Lord! By the love Thou bearest for me, show mercy on me.'' I interrupted by telling her that she should rather say, ''By the love that I have for Thee...!'' She got irritated at this suggestion and said, ''By Allah Himself! Had He not loved me, I would not be standing here before Him while you are in your bed.'' Then she fell prostrate and recited a few couplets purporting, ''I am growing more and more restless. How can one rest whose peace of mind is taken away by love, eagerness and constant anxiety? O, Allah! Show mercy and give some glad tidings.'' Then she prayed in a loud voice thus, ''O Allah! So far the matter between me and Thee has been a secret. Now people have come to know of it. O, Allah! Call me back.'' After saying this, she cried aloud and died on the spot.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760600-0000-4000-8000-000000000001", "structuralNodeId": "b0760300-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}, {"id": "f0760700-0000-4000-8000-000000000001", "structuralNodeId": "b0760300-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "A similar thing happened with Sirri (Rahmatullah alaih). He writes: \"I bought a slave woman to attend on me.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 76"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0770000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 77, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "77", "printedPageNumber": 77, "pdfPageNumber": 460, "sequenceIndex": 67, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0770100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—VII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0770200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—VIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0770000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (b)—Stories of the Pious", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "She served me for some time, but I was in the dark about her state of affairs. She had a corner in the house reserved for her salaat. After finishing her job, she would go there and offer her salaat. One night, I noticed her performing salaat and then supplicating before Allah. While making her supplication, she said, ''By the love Thou hast for me, do such and such a thing for me.'' I shouted out to her, ''O woman, say by the love that I have for Thee.'' She retorted, ''My Master, if He had not loved me, He would not have made me stand for salaat and deprive you thereof.'' Next morning I sent for her and said to her, ''You are a misfit in your present job. You are exclusively meant for Allah''s service.'' I then gave her some gifts and set her free.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770200-0000-4000-8000-000000000001", "structuralNodeId": "b0770100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770300-0000-4000-8000-000000000001", "structuralNodeId": "b0770100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Sirri Saqti (Rahmatullah alaih) writes about another woman: \"When she stood up for Tahajjud she would say, ''O Allah! Satan is but Thy creation. Thou hast full power over him. He sees me and I cannot see him. Thou seest him and hast control over all his actions, while he has no control over Thee; O, Allah! repel the evil that he wishes to do me. Requit the wrong he may do to deceive me. I seek Thy refuge from his evil designs and with Thy help I cast him away.'' Thereafter she would cry bitterly. And as a result thereof she lost the sight of one eye. People admonished her to stop excessive weeping, lest she should lose her other eye as well. She replied, \"If it is destined to be an eye of Paradise, Allah will grant me better than this; but if it be that of Hell, then the sooner it is lost the better.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770400-0000-4000-8000-000000000001", "structuralNodeId": "b0770200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—VIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770500-0000-4000-8000-000000000001", "structuralNodeId": "b0770200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Shaikh Abu Abdullah Jilaa says: \"One day my mother asked my father to fetch some fish from the market. My father left for the market and I also accompanied him. The fish was bought and we needed a porter to carry it for us. We engaged a boy who was standing there and who had offered to do the job for us. He put the load on his head and followed us. While we were on our way, we happened to hear the Azaan. The boy abruptly spoke, ''Allah''s summoner has summoned me; I have to take my wudhu too. I shall now carry the fish after salaat. If you like you may wait, otherwise here it is.'' Saying this he put the load down and left for the musjid. My father thought when the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0780000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 78, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "78", "printedPageNumber": 78, "pdfPageNumber": 461, "sequenceIndex": 68, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0780100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—IX", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0780200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—X", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0780000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "poor boy could place his trust in Allah so much, we must as well do so in a greater degree. He, therefore, left the fish there and took me to the musjid. When we three returned after saying salaat, we found the fish lying in the same place as we had left it. The boy then carried it to our house. My father related the strange story to my mother who insisted that the boy should be invited to eat some fish with us. When the invitation was extended to him, he said, ''Excuse me I am fasting.'' My father then requested him to have iftaar at our place. To this he said, ''It is not possible for me to return once I am gone. Just possibly, I may stay in a musjid close to your place; if so, then I shall join you in your dinner.'' Saying this he went to the musjid and returned after Maghrib. When the dinner was over, I showed him the room where he could rest in privacy. Now, there lived a crippled woman in our neighbourhood. We were surprised to see her walking quite hale and hearty. When we enquired from her how she got cured, she said, ''I prayed to Allah to heal me for the sake of the blessings that your guest carries. No sooner I prayed than I was healed.'' When we went to find the boy in the room where we had left him, the door was shut and the boy was nowhere to be seen.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780200-0000-4000-8000-000000000001", "structuralNodeId": "b0780100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—IX", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780300-0000-4000-8000-000000000001", "structuralNodeId": "b0780100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said of a pious man that once he had a sore on his foot. According to the opinion of the surgeons, if his foot was not amputated, the sore might prove fatal. His mother proposed that the operation should be done while he was absorbed in his salaat. This was done, and no pain was felt by him.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780400-0000-4000-8000-000000000001", "structuralNodeId": "b0780200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—X", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}, {"id": "f0780500-0000-4000-8000-000000000001", "structuralNodeId": "b0780200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Abu ''Aamir (Rahmatullah alaih) says, \"I saw a slave woman on sale for a very small sum. She was very emaciated and her hair was dirty. I took pity on her and purchased her. I said to her, ''Come, woman, let us go and make purchases for Ramadhaan.'' She remarked, ''Alhamdulillah, all the months are alike for me.'' She fasted on all days and stood in salaat for all nights. When Eid drew near, I said to her, ''Woman! You will go with me tomorrow to make purchases for Eid.'' She remarked, ''My master! You are too much absorbed in this world.'' She then went into", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 78"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0790000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 79, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "79", "printedPageNumber": 79, "pdfPageNumber": 462, "sequenceIndex": 69, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0790100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XI", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0790000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (b)—Stories of the Pious", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "her room and started her salaat. She was reciting Soorah Ibrahim and when she reached the 16th verse of the Soorah (viz.,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "مِنْ وَرَائِهِ جَهَنَّمُ وَيُسْقَىٰ مِنْ مَاءٍ صَدِيدٍ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Hell is before him and he is made to drink boiling fetid water\", which described the doom of a disbeliever, she repeated it again and again, and then gave out a cry and fell dead.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790400-0000-4000-8000-000000000001", "structuralNodeId": "b0790100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}, {"id": "f0790500-0000-4000-8000-000000000001", "structuralNodeId": "b0790100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Everybody knows Umar bin Abdul Aziz (Rahmatullah alaih). After the four Khulafaa-ur Raashideen he is the most eminent Khalifah. His wife says, \"There may be other people more particular about wudhu and salaat; but I have never seen anybody fearing Allah more than my husband. After his daily Ishaa, he would sit at a place reserved for his salaat and raise his hands in supplication and keep crying before Allah till sleep overpowered him. Whenever he woke during the night, he would again start praying and crying before Allah.\"\n\nIt is said that since his becoming Khalifah he never shared the bed with his wife. His wife was the daughter of the great King Abdul Malik. Her father had given her much jewellery in dowry, which included a marvellous diamond. He said to his wife, \"Either part with all your jewellery for the sake of Allah, so that I may deposit it in the Baitul Maal or be separated from me. I would not like to live in a house where there is so much wealth.\" His wife replied, \"I can part with a thousand times more wealth, but I cannot leave you.\" She then deposited everything she had in the Baitul Maal. After the death of Umar bin Abdul Aziz, when Yazeed son of Abdul Malik succeeded him as Khalifa, he said to his sister, \"If you like you may have your jewellery back from the Baitul Maal.\" She replied, \"How can the wealth I discarded during my husband''s lifetime, satisfy me after his death.\"\n\nUmar bin Abdul Aziz was on his death-bed when he inquired from the persons round him about the cause of his disease. Someone said, \"People think it is the effect of black magic.\" He said, \"No, it is not magic.\" He then sent for a particular slave of his and said to him, \"What made you poison me?\" He replied, \"One hundred dinaars and a", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 79"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0800000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 80, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "80", "printedPageNumber": 80, "pdfPageNumber": 463, "sequenceIndex": 70, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0800100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0800200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0800000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "promise of liberty,\" Umar bin Abdul Aziz (Rahmatullah alaih) took those dinaars from the slave and deposited them in the Baitul Maal, and advised him to run away to some distant place where he could not be seized.\n\nJust before his death, Muslimah (Rahmatullah alaih) came to him and said, \"Nobody has ever treated his children as you are doing. None of your thirteen sons has anything to live on.\" He sat up in his bed and said, \"I have not held back from my sons what they were entitled to. I have, of course, refused them what was actually due to others. If my sons are righteous, then Allah will surely be their guardian as He has said in His Book: He is the guardian of the righteous (VII: 196)'', but if they are wrong-doers, then why should I care for them?\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800200-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800300-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Muhammad bin Munkadir (Rahmatullah alaih) was a Hafiz of Hadith. One night, he wept excessively in his Tahajjud. When someone inquired about it, he said, \"During Qiraat, I came across the following words of the Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800400-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَبَدَا لَهُمْ سَيِّئَاتُ مَا كَسَبُوا وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800500-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And the evils that they earned will confront them; and they will be surrounded by what they used to scoff at.\" (XXXIX: 48)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800600-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "He was very anxious and worried at the time of his death, and said that these same words of the Qur''an were looming before him.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800700-0000-4000-8000-000000000001", "structuralNodeId": "b0800200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800800-0000-4000-8000-000000000001", "structuralNodeId": "b0800200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Thaabit Banaani (Rahmatullah alaih) is another Hafiz of Hadith. He used to cry a great deal while supplicating before Allah. Someone warned him that he would lose his eyesight if he did not stop weeping like that. He replied to him, \"What use are these eyes if these do not weep before Allah.\"\n\nHe used to ask in his prayer, \"O, Allah! Permit me to offer my salaat in my grave, if ever you grant this privilege to any of Thy slaves!\" Abu Sanaan (Rahmatullah alaih) narrates, \"By Allah! I was among those present at the burial of Thaabit Banaani. Just after he had been placed in his grave, one of the bricks from the side fell off. I peeped into the pit to find to my great amazement, that Thaabit was offering", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0810000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 81, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "81", "printedPageNumber": 81, "pdfPageNumber": 464, "sequenceIndex": 71, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0810000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (b)—Stories of the Pious", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 81"}, {"id": "f0810100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "his salaat. I said to a person standing by my side; ''Look what is that.'' He advised me to keep quiet. After the burial, we went to his daughter and inquired from her, ''What was the special practice of your father?'' She wanted to know what made us put that question. We related to her the incident at the grave. She said, ''He has been constant in Tahajjud for fifty years and prayed every morning before Allah to allow him to offer salaat in the grave if that privilege could be granted to anybody.''\n\nBefore finishing this chapter, I give below the pursuits (as regards salaat) of some of our eminent Muslim ancestors:\n\n1. Imaam Ahmad bin Hambal (Rahmatullah alaih) is the famous Imaam of one of the four schools of Muslim jurisprudence. Besides being engaged in his usual work, he used to offer daily three hundred rakaats of nafl salaat. After he was lashed by the king for refusal to submit to the royal edict, he became very weak and reduced his routine nafl salaat to one hundred and fifty rakaats. We should not forget that he was eighty at that time.\n\n2. Imaam Shaafi''ee (Rahmatullah alaih) another eminent Imaam of Muslim jurisprudence, used to finish reciting the Qur''an sixty times in his salaat during Ramadhaan. A person narrates, \"I remained with Imaam Shaafi''ee for several days and found him sleeping only for a while at night.\"\n\n3. Imaam Abu Haneefa (Rahmatullah alaih) is famous for his vigil. It is said that for thirty, forty or fifty years (according to the information of different narrators) he offered his Fajr prayer with the wudhu for Ishaa. He would go to sleep only for a few minutes in the afternoon saying, \"It is sunnat to sleep in the afternoon.\"\n\n4. It is said about Sa''eed bin Musayyab (Rahmatullah alaih) that for fifty years he offered his Fajr salaat with the wudhu performed at Ishaa. Imaam Ghazzali (Rahmatullah alaih) on the authority of Abu Taalib Makki reported the same practice by no less than forty Taabi''ees, some of whom had been doing it for forty years continuously.\n\n5. Muhammad bin Nasr (Rahmatullah alaih) is a famous Muhaddith. His devotion to salaat had no", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 81"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0820000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 82, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "82", "printedPageNumber": 82, "pdfPageNumber": 465, "sequenceIndex": 72, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0820000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 82"}, {"id": "f0820100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "parallel. Once while in salaat, he was stung on his forehead by a wasp and though blood came out, neither did he stir nor did he allow it to disturb his devotion in salaat. It is said that in salaat, he stood motionless like a stick planted in the ground.\n\n6. It is reported about Baqi bin Mukhallid (Rahmatullah alaih) that he used to recite the complete Qur''an every night in thirteen rakaats of Tahajjud and Witr.\n\n7. Hannaad (Rahmatullah alaih) is a Muhaddith. One of his pupils narrates, \"Hannaad used to weep very much. One day after he had finished our lesson in the morning, he continued to offer nafl salaat till midday. He went to his place for a short interval and then returned for his Zuhr. He again engaged himself in nafl salaat till Asr. Between Asr and Maghrib, he recited the Qur''an. I left him after Maghrib. I said to one of his neighbours, ''Our Shaikh prays so much. It is really wonderful.'' He said, ''He had been doing this for the last seventy years. You will wonder still more if you see his prayers during the night.''\"\n\n8. Masrooq (Rahmatullah alaih) is another Muhaddith. His wife narrates, \"He used to offer such long rakaats that his legs would get swollen and I sat behind weeping in pity for him.\"\n\n9. Abu Itaab Sulami (Rahmatullah alaih) is reported to have been fasting during the day and weeping during the night for full forty years.\n\n10. It is said about a Sayyid that continuously for twelve days he has been offering his salaat with the same wudhu. For fifteen years, his back had not touched the bed. He would also go without food for days together.\n\nBesides the above, there are numerous records of the pious pursuits of the heroes of Islamic History. It is difficult to cover all of them in this book. All that has been said here is sufficient to serve as examples. May Allah, through His Grace, grant me and the readers of this book the strength to follow in the footsteps of these blessed people! Aameen!", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 82"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0830000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 83, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "83", "printedPageNumber": 83, "pdfPageNumber": 466, "sequenceIndex": 73, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0830100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER—III", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0830200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "QUOTATIONS FROM HADITH", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0830300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—I", "sourceIdentifier": "I", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0830400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0830000-0000-4000-8000-000000000001", "structuralNodeId": "b0830100-0000-4000-8000-000000000001", "sequenceIndex": 0, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830100-0000-4000-8000-000000000001", "structuralNodeId": "b0830200-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "QUOTATIONS FROM HADITH", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830200-0000-4000-8000-000000000001", "structuralNodeId": "b0830300-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830300-0000-4000-8000-000000000001", "structuralNodeId": "b0830300-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عمار بن ياسر رضي الله عنه قال سمعت رسول الله ﷺ يقول إن الرجل لينصرف وما كتب له إلا عشر صلاته تسعها ثمنها سبعها سدسها خمسها ربعها ثلثها نصفها رواه أبو داود والنسائي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830400-0000-4000-8000-000000000001", "structuralNodeId": "b0830300-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Ammar bin Yaasir (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"When a person finishes his salaat, he gets one tenth, one ninth, one eighth, one seventh, one sixth, one fifth, one fourth, one third or one half of the maximum reward (according to the quality of salaat performed by him).\"\n\nThis shows that the reward is given in proportion to the sincerity and devotion with which salaat is performed. So much so, that some get only one tenth of the total reward. There are others who get a reward ranging from one tenth to one half of the maximum. It is also correct to say that there are some who receive the reward in full and there are others who get no reward at all.\n\nIt is stated in a hadith that Allah has a standard for fardh salaat. An account is kept of the measure by which a salaat falls short of that standard.\n\nIt is said in the hadith that devotion in salaat will be the first thing to be taken away from the world. A time will come when not a single person in the whole congregation will offer his salaat with proper devotion.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830500-0000-4000-8000-000000000001", "structuralNodeId": "b0830400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}, {"id": "f0830600-0000-4000-8000-000000000001", "structuralNodeId": "b0830400-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رُوِيَ عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ ﷺ فَمَنْ صَلَّى الصَّلَاةَ لِوَقْتِهَا وَأَسْبَغَ لَهَا وُضُوءَهَا وَأَتَمَّ لَهَا قِيَامَهَا وَخُشُوعَهَا وَرُكُوعَهَا وَسُجُودَهَا خَرَجَتْ وَهِيَ بَيْضَاءُ مُسْفِرَةٌ تَقُولُ حَفِظَكَ اللَّهُ كَمَا حَفِظْتَنِي مَنْ صَلَّاهَا لِغَيْرِ وَقْتِهَا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 83"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0840000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 84, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "84", "printedPageNumber": 84, "pdfPageNumber": 467, "sequenceIndex": 74, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0840000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَلَمْ يُسْبِغْ لَهَا وُضُوءَهَا وَلَمْ يُتِمَّ لَهَا خُشُوعَهَا وَلَا رُكُوعَهَا وَلَا سُجُودَهَا خَرَجَتْ وَهِيَ سَوْدَاءُ مُظْلِمَةٌ تَقُولُ ضَيَّعَكَ اللَّهُ كَمَا ضَيَّعْتَنِي حَتَّى إِذَا كَانَتْ حَيْثُ شَاءَ اللَّهُ لُفَّتْ كَمَا يُلَفُّ الثَّوْبُ الْخَلِقُ ثُمَّ ضُرِبَ بِهَا وَجْهُهُ رَوَاهُ الطَّبَرَانِي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 84"}, {"id": "f0840100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 84"}, {"id": "f0840200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas (Radhiyallaho anho) narrates that he heard the Holy Prophet (Sallallaho alaihe wasallam) saying, \"When a person offers his salaat at its fixed hours with proper wudhu, with humility and submission and with qiyaam, ruku and sajdah done satisfactorily, then such a salaat rises up in a bright and beautiful form and blesses the person in words: ''May Allah guard you as you have guarded me.'' On the other hand, if a person is not punctual with his salaat nor does he perform wudhu, qiyaam, ruku and sajdah properly, then salaat rises up in an ugly and dark shape and curses the person saying, ''May Allah ruin you as you have ruined me!'' Then it is flung back like a dirty rag at the face of the person.\"\n\nLucky are those whose salaat is so perfect in all respects that this most important worship of Allah would pray for them. But what to say about the salaat which most of the people are wont? They go into sajdah direct from ruku, and they hardly lift their head from the first sajdah when they go for the second like a crow pecking at something. The curse that such a person deserves is mentioned in this hadith. When the salaat is cursing us then what else can check our downfall? This is why the condition of the Muslims is deteriorating day by day in every nook and corner of the world.\n\nThe same description is given in another hadith, with the addition that a salaat offered by a person with sincerity and devotion rises up highly illuminated, the gates of Heaven are let open for its reception, and then it intercedes (before Allah) for His devotee.\n\nThe Prophet (Sallallaho alaihe wasallam) has said, \"The likeness of a person not bowing fully in ruku is that of a pregnant woman aborting just before delivery.\"\n\nIn a hadith, it is stated, \"There are many fasting persons who get nothing out of their fast except hunger and thirst, and there are many worshippers who keep a vigil but get nothing from their vigil except sleeplessness.\"\n\nHadhrat Aa''ishah (Radhiyallaho anha) narrates that", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 84"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0850000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 85, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "85", "printedPageNumber": 85, "pdfPageNumber": 468, "sequenceIndex": 75, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0850100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—III", "sourceIdentifier": "III", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0850000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}, {"id": "f0850100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "she heard the Prophet (Sallallaho alaihe wasallam) saying, \"Allah has decided to save (from punishment of the Hereafter) a person coming before Him who has been offering salaat five times daily at its fixed hours, with due sincerity and devotion and with proper wudhu. As regards a person who does not so come before Allah, there is no guarantee for him. He may be forgiven by Allah''s special Grace or taken to task.\n\nOnce the Prophet (Sallallaho alaihe wasallam) came to his companions and said, \"Do you know what Allah has said?\" The companions replied, \"Allah and His Apostle know best.\" He repeated the question twice and the companions made the same reply each time. Then he said, \"Allah says, ''By my Greatness and My Glory, I must bring into Paradise the person offering salaat five times daily at its fixed hours. As regards the person who does not ensure his salaat, I may forgive him by My mercy or take him to task.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}, {"id": "f0850200-0000-4000-8000-000000000001", "structuralNodeId": "b0850100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}, {"id": "f0850300-0000-4000-8000-000000000001", "structuralNodeId": "b0850100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال سمعت رسول الله ﷺ يقول إن أول ما يحاسب به العبد يوم القيامة من عمله صلاته فإن صلحت فقد أفلح وأنجح وإن فسدت فقد خاب وخسر وإن انتقص من فريضته قال الرب انظروا هل لعبدي من تطوع فيكمل بها ما انتقص من الفريضة ثم يكون سائر عمله على ذلك", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}, {"id": "f0850400-0000-4000-8000-000000000001", "structuralNodeId": "b0850100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates, \"We heard the Prophet (Sallallaho alaihe wasallam) saying, ''The first among the doings of a person to be reckoned for on the Day of Judgement shall be his salaat. A person will succeed and attain his goal if his salaat is accepted, and he will fail and lose badly if it is rejected. If any deficiency is found in his fardh salaat, Allah will say (to the Angels): \"Look for any nafl salaat in his account\". Then the deficiency in his fardh salaat will be made good by nafl salaat. The rest of the religious practices (viz. Fast, Zakaat etc.) will then be reckoned for in the same manner.''\n\nThis hadith shows that we should have adequate nafl salaat to our credit to make up any deficiency in our fardh salaat. It is a habit with many people to say, \"It is enough to observe only the fardh salaat. nafl salaat is meant for the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 85"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0860000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 86, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "86", "printedPageNumber": 86, "pdfPageNumber": 469, "sequenceIndex": 76, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0860100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—IV", "sourceIdentifier": "IV", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0860000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}, {"id": "f0860100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "eminent. No doubt it is enough to offer fardh salaat properly, but is it so easy to observe it to the proper standard? Most probably, there will always be some deficiency in one respect or the other, and there is no way out to make up that deficiency except through nafl salaat.\n\nThere is another hadith which deals with this point more elaborately. It declares, \"Salaat is the foremost duty enjoined by Allah and the first thing to be presented before Allah, and the first thing to be reckoned for on the Day of Judgement. If the fardh salaat is found wanting in quality, then its deficiency will be made good through nafl salaat. The fasts of Ramadhaan will be the next to be reckoned for and any deficiency therein will be made good through nafl Fasts. Then Zakaat shall be reckoned for in a similar manner. If after adding nafl the good deeds are found heavier in the scales, the person concerned shall be sent to Paradise, otherwise he shall meet his doom in Hell.\" Such was the practice of the Prophet (Sallallaho alaihe wasallam) that when anybody embraced Islaam at his hand, the first thing he taught him was salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}, {"id": "f0860200-0000-4000-8000-000000000001", "structuralNodeId": "b0860100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}, {"id": "f0860300-0000-4000-8000-000000000001", "structuralNodeId": "b0860100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عبد الله بن قرط رضي الله عنه قال قال رسول الله ﷺ أول ما يحاسب به العبد يوم القيامة الصلاة فإن صلحت صلح سائر عمله وإن فسدت فسد سائر عمله رواه الطبراني", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}, {"id": "f0860400-0000-4000-8000-000000000001", "structuralNodeId": "b0860100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Qurt (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying \"Salaat will be the first thing to be reckoned for on the Day of Judgement. If this is found satisfactory, then the rest of the deeds will also come out as such. If this is not so, then the remaining deeds are sure to be found wanting.\n\nHadhrat Umar (Radhiyallaho anho) during his caliphate had issued a proclamation to all the officers under him saying, \"I regard salaat as the most important duty. A person who ensures salaat is likely to observe other injunctions of Islam as well; but if he discards salaat, he will more easily damage the rest of Islaam.\"\n\nThe above saying of the Prophet (Sallallaho alaihe wasallam) and the proclamation of Hazrat Umar (Radhiyallaho anho) are also corroborated by another hadith, \"Satan", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0870000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 87, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "87", "printedPageNumber": 87, "pdfPageNumber": 470, "sequenceIndex": 77, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0870100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0870000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "is scared of a Muslim so long as he is mindful of his salaat; but no sooner he neglects the salaat than Satan descends on him and becomes hopeful of leading him astray, and then he can easily be lured to commit more serious wrongs and major sins. This is exactly what is meant by Almighty Allah when He says,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! salaat preserveth from lewdness and inequity\" (XXIX: 45)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870400-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870500-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عبد الله بن أبي قتادة رضي الله عنه قال رسول الله ﷺ أسوأ الناس سرقة الذي يسرق من صلاته قالوا يا رسول الله كيف يسرق من صلاته قال لا يتم ركوعها ولا سجودها رواه أحمد", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870600-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Abu Qataadah (Radhiyallaho anho) narrates, \"The Holy Prophet (Sallallaho alaihe wasallam) once said, ''The worst thief is one who steals from his salaat.'' The companions inquired, ''How can one steal from his salaat? O, Prophet of Allah!'' He replied, ''When one does not do his ruku and sajdah properly.''\n\nThere are many other Ahaadith conveying the same meaning. Stealing is a very disgraceful act and a thief is despised by everybody. What about a person who is declared ''the worst thief'', by no less a person than the Prophet himself?\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates, \"Once the Prophet (Sallallaho alaihe wasallam) looked up towards the sky and said, ''The knowledge of Deen is soon to be taken away from this world.'' Ziyaad (Radhiyallaho anho), who was also present there inquired, ''How can the knowledge of Deen be taken away, O, Prophet of Allah (Sallallaho alaihe wasallam), when we are teaching the Qur''an to our children and this process will continue in our posterity?'' The Prophet (Sallallaho alaihe wasallam) said to him, ''Ziyaad! I always took you to be an intelligent person. Don''t you see that the Jews and the Christians are also teaching their Bibles to their children? Has this prevented", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0880000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 88, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "88", "printedPageNumber": 88, "pdfPageNumber": 471, "sequenceIndex": 78, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0880100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0880000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "their deterioration?\" One of Hadhrat Abu Darda''s (Radhiyallaho anho) pupils says \"After hearing this hadith from Hadhrat Abu Darda (Radhiyallaho anho), I went to Hadhrat Ubaadah (Radhiyallaho anho) and related the hadith to him.\" He said, \"Abu Darda (Radhiyallaho anho) is quite right. May I tell you the first thing that will be taken away from this world? It is devotion in salaat. You will see that not a single person in the full congregation is saying his salaat with devotion.\" Hadhrat Huzaifah (Radhiyallaho anho), the confidante of the Prophet (Sallallaho alaihe wasallam), was also heard saying, \"Devotion in salaat shall be the first thing to disappear.\"\n\nIt is said in a hadith, \"Allah does not pay any attention to that salaat with which ruku and sajdah are not performed properly.\"\n\nAnother hadith says, \"A person has been offering salaat for sixty years, but in fact not a single salaat of his is accepted by Allah. This is because he has been careless about his ruku in some salaats and about his sajdah in others.\"\n\nA great stress is laid on the proper performance of salaat in the famous Epistles of Shaikh Ahmad Sirhindi (Rahmatullah alaih). His discourses on the subject cover a good portion of the Epistles. In one of them he writes, \"It is necessary among other things that, we should be particular about keeping the fingers of our hands together while in sajdah and separated while in ruku. These regulations are not without a purpose.\" He further writes, \"To keep our glance at the place of sajdah while standing, on our feet while in ruku, on our nose while in sajdah, and on our hands while in Qa''dah, goes a long way in keeping the desired concentration in salaat.\" When such ordinary regulations, which are only mustahab, increase the value of our salaat, you can well imagine how much benefit we shall derive if we be particular of other regulations, which are either sunnat or otherwise more important.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880200-0000-4000-8000-000000000001", "structuralNodeId": "b0880100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880300-0000-4000-8000-000000000001", "structuralNodeId": "b0880100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ أُمِّ رُومَانَ رَضِيَ اللَّهُ عَنْهَا وَالِدَةِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ رَآنِي أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ عَنْهُ أَتَمَيَّلُ فِي صَلَاتِي فَزَجَرَنِي زَجْرَةً كِدْتُ أَنْصَرِفُ مِنْ صَلَاتِي قَالَ سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ إِذَا قَامَ أَحَدُكُمْ فِي الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0890000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 89, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "89", "printedPageNumber": 89, "pdfPageNumber": 472, "sequenceIndex": 79, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0890000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فَلْيُسَكِّنْ أَطْرَافَهُ لَا يَتَمَيَّلْ تَمَيُّلَ الْيَهُودِ فَإِنَّ سُكُونَ الْأَطْرَافِ فِي الصَّلَاةِ مِنْ تَمَامِ الصَّلَاةِ\nأَخْرَجَهُ الْحَكِيمُ التِّرْمِذِيُّ عَنِ ابْنِ عُمَرَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Umme Roomaan (wife of Abu Bakr) (Radhiyallaho anha) narrates, \"Once I was offering my salaat, when I unknowingly started leaning sometimes to one side and sometimes to the other. Hadhrat Abu Bakr (Radhiyallaho anho) saw me doing this and reprimanded me so harshly that I was about to abandon my salaat with fear. He told me later that he had heard the Prophet (Sallallaho alaihe wasallam) saying, \"When a person stands for salaat, he should keep his body at rest and he should not behave like the Jews, since to remain motionless is one of the complements of salaat.\"\n\nKeeping the body at rest during salaat is enjoined in many ahaadith. In the beginning, it was a habit with the Prophet (Sallallaho alaihe wasallam) that he kept looking towards the heaven in expectation of Hadhrat Jibra-eel (Alayhis salaam) to bring him some revelation, so much so that his eyes would sometimes rise up unconsciously even during salaat. When the first two verses of Soorah XXIII (viz.,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "(Successful indeed are the believers who are humble in their salaat)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "were revealed, he began to keep his gaze down while in salaat. It is also said about the companions that in the beginning they would sometime cast their glances here and there during their salaat but, after these verses were revealed, they gave up this practice. Explaining these verses, Hadhrat Abdullah bin Umar (Radhiyallaho anho) says, \"When the Sahabah stood for salaat they never looked this side or that side. They remained attentive in salaat with their eyes fixed at the place of sajdah; totally absorbed in Allah, their Lord. Someone inquired from Hadhrat Ali (Radhiyallaho anho), ''What is devotion?'' He replied, ''Concentration in salaat is included in devotion.''\"\n\nHadhrat Ibn Abbas (Radhiyallaho anho) says, \"Humble (mentioned in the above verses) are those who fear Allah and remain motionless in salaat.\"\n\nHadhrat Abu Bakr (Radhiyallaho anho) narrates, \"Once", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0900000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 90, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "90", "printedPageNumber": 90, "pdfPageNumber": 473, "sequenceIndex": 80, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0900100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VII", "sourceIdentifier": "VII", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0900000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "the Prophet (Sallallaho alaihe wasallam) said, ''Seek refuge in Allah from sanctimonious devotion.'' We inquired, ''What is sanctimonious devotion, O Prophet of Allah! (Sallallaho alaihe wasallam).'' He replied, ''To feign concentration, with nifaaq lurking in the heart.''\n\nHadhrat Abu Darda (Radhiyallaho anho) relates a similar hadith in which the Prophet (Sallallaho alaihe wasallam) is reported to have said, \"Hypocritical devotion is that in which a person outwardly pretends concentration, while his heart is devoid of that.\"\n\nHadhrat Qataadah (Radhiyallaho anho) says, \"For devotion in salaat, the heart should be full of Allah''s fear, and the gaze should be kept down.\"\n\nThe Prophet (Sallallaho alaihe wasallam) once saw a person fondling his beard while in salaat. He remarked, \"If his heart were blessed with devotion, then his entire body would be at rest.\"\n\nHadhrat Aa''ishah (Radhiyallaho anha) once inquired from the Prophet (Sallallaho alaihe wasallam) as to what his opinion was about the practice of looking around while in salaat. He said, \"It is a damage to salaat caused by Satan.\"\n\nOnce the Prophet (Sallallaho alaihe wasallam) said, \"People in the habit of looking up while in salaat must give up that habit, lest their gaze may become fixed and not return to them.\"\n\nIt has been said by many of the companions and their successors that devotion means tranquillity in salaat. The Prophet (Sallallaho alaihe wasallam) is reported (by many narrators) to have said, \"Offer each salaat (with) such (devotion) as if it were the last salaat of your life.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900200-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900300-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عمران بن حصين رضي الله عنه قال سئل النبي ﷺ عن قول الله تعالى إن الصلاة تنهى عن الفحشاء والمنكر فقال من لم تنهه صلاته عن الفحشاء والمنكر فلا صلاة له كذا في الدر المنثور", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900400-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Imraan bin Husain (Radhiyallaho anho) narrates, Someone inquired of the Prophet (Sallallaho alaihe wasallam) about the meaning of the verse in Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0910000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 91, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "91", "printedPageNumber": 91, "pdfPageNumber": 474, "sequenceIndex": 81, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0910000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 91"}, {"id": "f0910100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 91"}, {"id": "f0910200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! Salaat restrains from shameful and unjust deeds.\" (XXIX: 45)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 91"}, {"id": "f0910300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "He replied, \"Salaat is no salaat if it does not preserve one from lewdness and iniquity.\"\n\nNo doubt, salaat is a very valuable service and when offered properly, results in preservation from all undesirables. If this result is not achieved, then there is something lacking in the proper performance of salaat. There are many other ahaadith conveying this meaning. Hadhrat Ibn Abbas (Radhiyallaho anho) says, \"Salaat has the power to check the inclination to sins.\"\n\nHadhrat Abul Aaliyah (Radhiyallaho anho) explaining the same verse of the Qur''an writes: \"There are three essentials of salaat: Sincerity, Fear of Allah, and His remembrance. Salaat is no salaat if these three are missing. Sincerity heralds virtuous deeds, fear of Allah expels vices, and His remembrance is the Qur''an, which in itself is a guidance towards good and guard against evil.\"\n\nHadhrat Ibn Abbas (Radhiyallaho anho) reports that the Prophet (Sallallaho alaihe wasallam) once said, \"Salaat that does not prevent from lewdness and iniquity instead of bringing close to Allah, takes away from Him.\"\n\nHadhrat Ibn Mas''ood (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"A person who does not follow up his salaat, has actually offered no salaat. To follow up the salaat is to shun lewdness and iniquity.\"\n\nHadhrat Abu Hurairah (Radhiyallaho anho) narrates, \"A person came to the Prophet (Sallallaho alaihe wasallam) and reported about a certain man, who was in the habit of offering salaat for the whole night and then committing a larceny before daybreak. The Prophet (Sallallaho alaihe wasallam) remarked, \"His salaat will very soon wean him off that sin.\" This shows that the evil habits can be got rid of by adhering to salaat with due sincerity. It is a difficult and lengthy affair to redeem each and every bad habit. On the contrary, it is easier and quicker to start offering salaat with proper care when through the blessings that follow it, bad habits are sure to disappear one by one.\" May Allah grant me strength to say my salaat properly!", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 91"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0920000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 92, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "92", "printedPageNumber": 92, "pdfPageNumber": 475, "sequenceIndex": 82, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0920100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VIII", "sourceIdentifier": "VIII", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0920000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 92"}, {"id": "f0920100-0000-4000-8000-000000000001", "structuralNodeId": "b0920100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 92"}, {"id": "f0920200-0000-4000-8000-000000000001", "structuralNodeId": "b0920100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن جابر رضي الله عنه قال قال رسول الله ﷺ أفضل الصلاة طول القنوت أخرجه ابن أبي شيبة ومسلم والترمذي وابن ماجه كذا في الدر المنثور وفيه أيضًا عن مجاهد في قوله تعالى وَقُومُوا لِلَّهِ قَانِتِينَ قال من القنوت الركوع والخشوع وطول الركوع يعني طول القيام وغض البصر وخفض الجناح والرهبة لله وكان الفقهاء من أصحاب محمد ﷺ إذا قام أحدهم في الصلاة يهاب الرحمن سبحانه وتعالى أن يلتفت أو يقلب الحصى أو يعبث بشيء أو يحدث نفسه بشيء من أمر الدنيا إلا ناسيًا حتى ينصرف أخرجه سعيد بن منصور وعبد بن حميد وابن جرير وابن المنذر وابن أبي حاتم والأصبهاني في الترغيب والبيهقي في شعب الإيمان", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 92"}, {"id": "f0920300-0000-4000-8000-000000000001", "structuralNodeId": "b0920100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Jabir (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"The best salaat is one with prolonged rakaats.\" Mujahid while explaining the verse", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 92"}, {"id": "f0920400-0000-4000-8000-000000000001", "structuralNodeId": "b0920100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَقُومُوا لِلَّهِ قَانِتِينَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 92"}, {"id": "f0920500-0000-4000-8000-000000000001", "structuralNodeId": "b0920100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And stand up with Qunoot to Allah (II-238)\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 92"}, {"id": "f0920600-0000-4000-8000-000000000001", "structuralNodeId": "b0920100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "says Qunoot comprises all such things as proper bowing; devotion, long rakaat, keeping the eyes down, lowering of shoulders in submission and fear of Allah. Whenever a companion of the Holy Prophet (Sallallaho alaihe wasallam) stood for salaat, he would not look here and there or level the pebbles at the place of sajdah (while prostrating) or engage himself in any absurd act, or think of any worldly thing (except unintentionally), all for fear of Allah.\n\nMany interpretations have been given to the word Qunoot, which occurs in the Qur''an in the verse mentioned in this hadith. According to one of the interpretations, Qunoot means silence. In the beginning of Islam, it was permissible to talk or to return greetings during salaat, but when this verse was revealed, talking during salaat was absolutely forbidden. Hadhrat Ibn Mas''ood (Radhiyallaho anho) says, \"In the beginning, whenever I visited the Prophet (Sallallaho alaihe wasallam), I would greet him with ''Assalamu alaikum'' and he would reply with ''Wa alaikumus salaam'' even if he were engaged in salaat. Once I visited him while he was in salaat and greeted him as usual, but he did not reply. I grew very anxious, fearing", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 92"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0930000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 93, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "93", "printedPageNumber": 93, "pdfPageNumber": 476, "sequenceIndex": 83, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0930000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 93"}, {"id": "f0930100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "that his attitude might be due to Allah''s displeasure for me. All sorts of anxious thoughts began to enter my mind. One moment, I would think the Prophet (Sallallaho alaihe wasallam) was angry with me and then some other saddening explanation would occur to me. When the Prophet (Sallallaho alaihe wasallam) finished his salaat, he said, \"Allah amends His commandments as He pleases. He has now forbidden any talking during salaat.\" He then recited the verse, ''And stand up with Qunoot to Allah'' (II: 238) and said, salaat is now meant exclusively to hymn the glory, praise and sanctity of Allah.\"\n\nHadhrat Mu''aawiyah bin Hakam Salami (Radhiyallaho anho) says, \"When I visited Madinah to embrace Islaam, I was taught many things. One of those was that I should say ''Yarhamukallaah'' when anybody sneezed and exclaimed ''Alhamdulillaah''. As I was new in Islaam, I did not know that this was not to be done during salaat. Once we were all standing in salaat when somebody sneezed. I immediately shouted, ''Yarhamukallaah''. Everybody began to stare at me. As I did not know then that we were not to talk in salaat, I protested saying, ''Why are you all casting these angry looks?'' They hushed me up with a gesture, but I could not understand their behaviour, although I decided to be quiet. When salaat was over, the Prophet (Sallallaho alaihe wasallam) called me. Neither did he beat or rebuke me, nor was he harsh to me. He simply said, ''It is not permitted to talk in salaat. Salaat is the occasion for praising the glory and magnificence of Allah and reciting the Qur''an.'' By Allah, I have never met, before or after, a teacher as affectionate as the Prophet (Sallallaho alaihe wasallam).\"\n\nAnother interpretation is given by Hadhrat Ibn Abbas (Radhiyallaho anho) in which he says that Qunoot means devotion. The words of Mujahid given above are based on this interpretation. Hadhrat Abdullah bin Abbas (Radhiyallaho anho) says, \"In the beginning, the Prophet (Sallallaho alaihe wasallam) used to tie himself up with a string while in Tahajjud, so that he might prevent sleep over-powering him. It was for this that the following verse was revealed in the Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 93"}, {"id": "f0930200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَىٰ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 93"}, {"id": "f0930300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"We have not revealed unto thee (Muhammad) (Sallallaho alaihe wasallam) this Qur''an that Thou should be distressed.\" (XX: 2)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 93"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0940000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 94, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "94", "printedPageNumber": 94, "pdfPageNumber": 477, "sequenceIndex": 84, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0940000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 94"}, {"id": "f0940100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is reported in many ahaadith that the Prophet''s (Sallallaho alaihe wasallam) feet would get swollen on account of standing for long hours during Tahajjud. Out of mere kindness and affection for his followers, he, however, advised them to be moderate in their worship, lest any excessiveness should lead to deflection. That is why we find him forbidding a woman from tying herself up for avoiding sleep during salaat.\n\nWe should remember that a salaat with long rakaat is surely better and more valuable, provided the endurance limits are not exceeded. After all, there is some meaning in the Prophet''s (Sallallaho alaihe wasallam) offering such lengthy salaat that would give him swollen feet. When the companions requested him to reduce his toil in worship, as he had been assured of forgiveness in Soorah Fath:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 94"}, {"id": "f0940200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 94"}, {"id": "f0940300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "(That Allah may forgive thee of thy sins that which is past and that which is to come (XLVIII: 2),", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 94"}, {"id": "f0940400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "he used to say, \"Why should I not, then, be a grateful slave of Allah?\"\n\nIt is stated in a hadith that when the Prophet (Sallallaho alaihe wasallam) offered his salaat, his bosom would give a constant groaning sound, which resembled that of a grinding mill. In another hadith, this sound is likened to that of a boiling kettle. Hadhrat Ali (Radhiyallaho anho) narrates, \"On the eve of Badr, I noticed that the Prophet (Sallallaho alaihe wasallam) stood under a tree, busy in salaat and crying before Allah all night long till daybreak.\"\n\nIt is said in a number of ahaadith, \"Allah is very much pleased with certain persons one of them is he who forsakes his bed shared with his dear and lovely wife and engages himself in Tahajjud on a winter night. Allah is very much pleased with him, takes pride in him, and in spite of being All-knowing inquires from the angels, ''What made this slave of mine forsake his bed and stand up like this?'' The Angels reply, ''The hope of winning Thy Bounty and Grace, and the fear of Thy displeasure.'' At this Allah says, ''Listen, I bestow upon him what he hopes for and grant him refuge from what he is afraid of.''\"\n\nThe Prophet (Sallallaho alaihe wasallam) says, \"None receives a better reward from Allah more than he who is blessed to offer two rakaats of salaat.\"\n\nIt has often been mentioned in the Qur''an and ahaadith that the Angels are perpetually engaged in worship.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 94"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0950000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 95, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "95", "printedPageNumber": 95, "pdfPageNumber": 478, "sequenceIndex": 85, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0950100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "REQUISITES OF GOOD SALAAT SUGGESTED BY SOOFIA", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0950000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "There are some who shall remain in ruku and some in sajdah till eternity. Allah has combined all these postures of the Angels in our salaat, so that we may get our shares from each type of their worship. Recitation of the Qur''an in salaat is an addition over and above their worship. While salaat is the sum total of all the postures in the Angels'' methods of worship, it gives out its best when it is offered by a person possessing angelic habits. That is why the Prophet (Sallallaho alaihe wasallam) says, \"For (a good) salaat, keep your back and stomach light.\" The back of a person is said to be light when he has very few worldly encumbrances, and his stomach is light when he eats moderately to avoid indolence and laziness, which is a sure outcome of gluttony.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950200-0000-4000-8000-000000000001", "structuralNodeId": "b0950100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "REQUISITES OF GOOD SALAAT SUGGESTED BY SOOFIA", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950300-0000-4000-8000-000000000001", "structuralNodeId": "b0950100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Soofia write: \"There are twelve thousand virtues in salaat, which can be achieved through twelve points. If a person is to acquire full benefit from salaat, then, he must take care of these points. Sincerity is of course essential at every step. These points are as follows:\n\n1. Knowledge: An action performed without knowledge is far inferior to the one done with full knowledge about it. We should therefore know:\n(a) Which of the Islamic Practices are fardh and which are sunnat.\n(b) What is fardh and what is sunnat in wudhu and salaat.\n(c) How does Satan cause obstruction in the proper observance of salaat.\n\n2. Wudhu: We must try to:\n(a) Clean our heart of jealousy and malice, just as we wash the other parts of our body.\n(b) Keep ourselves clean of sins.\n(c) Be neither wasteful nor abstemious in the use of water.\n\n3. Dress: It should be:\n(a) Got through honest living.\n(b) Clean.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0960000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 96, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "96", "printedPageNumber": 96, "pdfPageNumber": 479, "sequenceIndex": 86, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0960000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 96"}, {"id": "f0960100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "(c) According to the Sunnat, e.g. the ankles should not be covered.\n(d) Simple, and should not display vanity and pride.\n\n4. Time: We should be:\n(a) Able to tell correct time at any moment.\n(b) Always watchful about Azaan.\n(c) Particular about the time of salaat, lest we should be too late for it.\n\n5. Qiblah: There are three things to be ensured in facing Qiblah:\n(a) We must face Qiblah physically.\n(b) Have the heart in union with Allah, for He is the Qiblah of the heart.\n(c) Be as attentive as a slave is before his master.\n\n6. Intention: For this we need to be particular about three things:\n(a) We must be definite as to what salaat we are offering.\n(b) Remain constantly conscious of our presence before Allah, Who sees us.\n(c) Have perfect faith that Allah know all that is in our hearts.\n\n7. Takbeer Tahreemah: The essentials of ''Takbeer Tahreemah'' are:\n(a) To pronounce the words correctly.\n(b) To raise both hands right up to the ears. This signifies that we have severed our connection with all, except Allah;\n(c) To feel the greatness of Allah in our heart when we say Allaho Akbar.\n\n8. Qiyaam: While in Qiyaam we should:\n(a) Keep our gaze at the place of sajdah.\n(b) Feel in our heart that we are standing before Allah.\n(c) Not think of anything else.\n\n9. Qiraat: The essentials of Qiraat are:\n(a) To recite the Qur''an with Tajweed.\n(b) To ponder on the meanings of what we recite.\n(c) To bind ourselves to what we recite.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 96"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0970000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 97, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "97", "printedPageNumber": 97, "pdfPageNumber": 480, "sequenceIndex": 87, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0970100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "SIGNIFICANCE OF WORDING OF SALAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0970000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 97"}, {"id": "f0970100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "10. Ruku: The essentials of Ruku are:\n(a) To keep the back quite straight i.e. the whole body above the legs should be in one straight line.\n(b) To hold the knees firmly with fingers spread apart.\n(c) To recite Tasbeeh with humility and devotion.\n\n11. Sajdah: The essentials of Sajdah are:\n(a) To place the hands flat and close to the ears;\n(b) To keep elbows raised above the ground.\n(c) To recite Tasbeeh with devotion.\n\n12. Qa''dah: The essentials of Qa''dah are:\n(a) To sit up on the left foot, keeping the right one erect.\n(b) To recite Tashahhud with devotion, keeping the meaning in mind, for it contains greetings for the Prophet (Sallallaho alaihe wasallam) and prayer for the Muslim brethren.\n(c) To consider the concluding Salaam a definite greeting to the Angels as well as the people on the right and on the left.\n\nAs has been said already, sincerity is the essence of all these points, which requires us:\n1. To offer salaat with the sole purpose of pleasing Allah.\n2. To understand that it is only through the grace and favour of Allah that we are able to offer salaat.\n3. To hope for the reward promised by Allah.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 97"}, {"id": "f0970200-0000-4000-8000-000000000001", "structuralNodeId": "b0970100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "SIGNIFICANCE OF WORDING OF SALAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 97"}, {"id": "f0970300-0000-4000-8000-000000000001", "structuralNodeId": "b0970100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Salaat is really a very blessed and auspicious observance. Every word uttered in it is imbued with Allah''s greatness and sanctity. Thanaa, the opening prayer of salaat, contains extremely virtuous and devotional meaning viz:\n\n(1) Subhaanakallaahumma: O, Allah! I praise Thy Sanctity. Thou art free from all blemishes. Thou art above anything that is not the best.\n\n(2) Wa bihamdika: I praise Thy Glory. All virtues and beauties are admittedly for Thee and befit Thee.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 97"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0980000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 98, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "98", "printedPageNumber": 98, "pdfPageNumber": 481, "sequenceIndex": 88, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0980100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "SALAAT OF FEW SAHAABAH, TAABI''EES AND SOOFIA", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0980000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 98"}, {"id": "f0980100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "(3) Wa tabaarakasmuka: Thy name is blessed: and in fact so blessed that blesses everything over which it is mentioned.\n\n(4) Wa ta''aalaa jadduka: Thy eminence is most exalted. Thy magnificence is most sublime.\n\n(5) Wa laa ilaaha ghairuk: There is no god save Thee. None has ever been and none shall ever be fit to be worshipped save Thee.\n\nSimilarly in ruku we recite \"Subhaana rabbiyal azeem\", which means:\n\n\"My Magnificent and Almighty Allah is free from all blemishes. I express my humbleness and weakness before His Greatness by bowing my head before Him (for the bowing of head is the symbol of humbleness and submission, just as a stiff neck is the sign of haughtiness and pride). I submit before all Thy commandments and I take upon me Thy service. I am at Thy command. Thou art really very Great and I submit before Thy greatness.\"\n\nSimilarly in sajdah we express our submission before Allah the Highest, and declare Him above all defects. Our head, which is considered as the most superb part of our body along with our eyes, ears, nose and tongue, is placed on ground before Him in the hope that He would show mercy and bestow His blessings on us. Standing with our hands folded before Him this was the first expression of our humbleness and submission. This was further augmented by the bending of our head in ruku and it reached its climax when we placed our head on the ground before Him. In fact the whole salaat is an indication of humbleness and submission, and therefore, a means of advancement and success in the world and in the hereafter. May Allah through His Kindness arouse me and all the Muslims to offer such a salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 98"}, {"id": "f0980200-0000-4000-8000-000000000001", "structuralNodeId": "b0980100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "SALAAT OF FEW SAHAABAH, TAABI''EES AND SOOFIA", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 98"}, {"id": "f0980300-0000-4000-8000-000000000001", "structuralNodeId": "b0980100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said about Hadhrat Hasan (Radhiyallaho anho) that whenever he performed wudhu, his face grew pale. When someone inquired from him its cause, he replied, \"It", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 98"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0990000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 99, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "99", "printedPageNumber": 99, "pdfPageNumber": 482, "sequenceIndex": 89, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0990000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 99"}, {"id": "f0990100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "is time to stand before the most Majestic and Irresistable Sovereign.\" On reaching the gate of the musjid he would say,\n\n\"O Allah! Thy slave is at Thy door, O the most Beneficent! Here is a sinner before Thee: Thou hast enjoined upon the good amongst us to overlook the faults of the bad. O Allah, Thou art Good and I am bad. So for the sake of all that is most beautiful in Thee, overlook all that is ugly in me. O, The most Bountiful.\"\n\nHe would then enter the musjid.\n\nZainul Aabideen (Rahmatullah alaih) used to offer one thousand rakaats of nafl salaat daily. He never missed his Tahajjud, whether in journey or at home. His face grew pale when he performed his wudhu and he would tremble when he stood in salaat. Somebody asked him the reason for that. He said, \"Don''t you know before Whom am going to stand?\" Once when he was engaged in salaat, a fire broke out in his house. He continued his salaat most calmly. When asked about it, he remarked, \"The fire of the hereafter kept me unmindful of the fire of this world.\" He once said, \"The pride of a proud person surprises me. The day before, he was a drop of a dirty fluid and tomorrow he will be carrion; and still he is proud.\" He used to say, \"It is strange that people do so much for the world, which is transitory, and do nothing for the hereafter, where they are to live for ever.\" He used to help the poor in the darkness of night, so that they should not even know who helped them. It came to light only after his death that no less than one hundred families were being supported by him.\n\nIt is said about Hadhrat Ali (Radhiyallaho anho) that the colour of his face would change and he would tremble at the approach of the hour of salaat. On being asked by someone he said, \"This is the time for discharging the trust which the Heaven and the Earth and even the mountains were afraid to bear. I do not know if I shall be able to discharge it.\"\n\nIt is said of Hadhrat Abdullah bin Abbas (Radhiyallaho anho) that, when he heard the Azaan, he wept so much that his shawl would get wet with his tears; his veins would swell and his eyes would become red. Somebody said to him, \"We do not see anything in the Azaan that should make you so nervous.\" He replied, \"If people understood what the mu''azzin announced to them, they would give up", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 99"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e1000000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 100, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "100", "printedPageNumber": 100, "pdfPageNumber": 483, "sequenceIndex": 90, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f1000000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 100"}, {"id": "f1000100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "sleep and forsake their comforts.\" He then explained to him the warning conveyed by each word of the Azaan.\n\nA person narrates, \"I happened to offer my Asr prayer with Zunnoon Misri (Rahmatullah alaih). When he uttered ''Allah'' (in takbeer), he was so much struck with awe on account of Allah''s Majesty, as though his soul had departed, and when he uttered ''Akbar'' I felt my heart would burst with fear of Allah.\n\nUwais Qarni (Rahmatullah alaih), a famous saint and the most exalted of all the Taabi''ees, would spend his whole night sometimes in ruku and sometimes in sajdah.\n\nAsaam (Rahmatullah alaih) once inquired from Haatim Zaahid Balkhi (Rahmatullah alaih), how he offered his salaat. He replied,\n\n\"When the hour for salaat draws near, I perform my wudhu thoroughly and go to the place of salaat. When I stand for salaat, I visualise the Ka''bah in front of me, the Siraat under my feet, Paradise on my right, Hell on my left and the Angel of death over my head; and I think that this is my last salaat; so I may have no opportunity to say another. Allah alone knows what goes on in my heart at that time. Then I say ''Allaho Akbar'' with full humility and recite the Holy Qur''an, pondering over its meaning. I do my ruku and sajdah with full humbleness and submission, and finish my salaat quite calmly, hoping that Allah will accept it through His mercy, and fearing that it may be rejected if it is judged on its merits.\"\n\n''Asaam (Rahmatullah alaih) asked him, \"Since when have you been offering such salaat?\" Haatim (Rahmatullah alaih) replied, \"I have been doing it for the last thirty years.\" Asaam (Rahmatullah alaih) wept and said, \"I have never been so fortunate as to offer a single salaat of this kind.\"\n\nIt is said that Haatim (Rahmatullah alaih) once missed his salaat with jamaat and felt for it too much. A couple of persons came to condole with him on this loss. He started weeping and then said, \"If I had lost one of my sons, half the population of Balkh town would have come to me for condolence, but on the loss of my jamaat you are the only people condoling with me. It is only because people regard the afflictions in the Hereafter as lighter than the affliction of this world.\"\n\nSa''eed bin Musayyab (Rahmatullah alaih), says, \"For", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 100"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e1010000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 101, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "101", "printedPageNumber": 101, "pdfPageNumber": 484, "sequenceIndex": 91, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f1010000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 101"}, {"id": "f1010100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "the last twenty years, I have never been out of the musjid at the time of the Azaan.\"\n\nMuhammad bin Waasi'' (Rahmatullah alaih) says, \"I love three things in this life; a friend who could warn me on my slips, bread sufficient to keep me alive; and salaat (with jamaat) such that Allah may condone its defects and give me reward for anything good in it.\"\n\nHadhrat Abu Ubaidah bin Jarraah (Radhiyallaho anho) was once leading the salaat. When the salaat was over, he said to the people, \"Satan made a dangerous attack on me while I was leading the salaat. He made me think that as I was leading salaat, I am the best of all of you. I shall never lead the salaat again.\"\n\nMaimoon bin Mahraan (Rahmatullah alaih) once reached the musjid when the jamaat was over. He recited ''Innaa lillaahi wa innaa ilaihi raaji-oon'' and said, \"The reward of this salaat with jamaat was dearer to me than sovereignty over Iraq.\"\n\nIt is said of the Companions that they would mourn for three days if they happened to miss the first takbeer and for seven days if they missed jamaat.\n\nBakr bin Abdullah once said, \"You can speak to your Lord and Master any time you like.\" \"How?\" inquired somebody. He replied, \"Perform your wudhu properly and stand up for salaat.\"\n\nAa''ishah (Radhiyallaho anha) says, \"The Holy Prophet (Sallallaho alaihe wasallam) would be among us (family members) talking and listening, but on approach of salaat hour, he would all of a sudden behave as if he had never known us and would be completely absorbed in Allah.\"\n\nIt is said of Sa''eed Tannookhi (Rahmatullah alaih) that, as long as he remained in salaat, tears would flow from his eyes incessantly.\n\nSomebody asked Khalaf bin Ayyoob (Rahmatullah alaih), \"Do not the flies annoy you in your salaat?\" His answer was: \"Even the bad characters in society patiently bear the lashes of the police to boast of their endurance afterwards. Why should I be disturbed by mere flies, while standing in the presence of my Creator?\"\n\nIt is said in ''Bahjatun nufoos'' that one of the Sahabah was once offering Tahajjud when a thief came and took away his horse. He noticed it, but he did not break his salaat. Somebody asked him, \"Why did you not break salaat and catch the thief?\" He replied, \"I was engaged in something far more valuable than the horse.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 101"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e1020000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 102, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "102", "printedPageNumber": 102, "pdfPageNumber": 485, "sequenceIndex": 92, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f1020000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 102"}, {"id": "f1020100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said about Ali (Radhiyallaho anho) that whenever an arrow got stuck into his body (in a battle), this was drawn out during his salaat. Once he got an arrow stuck into his thigh. This could not be extracted, in spite of several efforts, due to severe pain felt by him. When he was busy in his nafl salaat and prostrate in sajdah, the people drew out the arrow with force. When he finished his salaat, he asked the people who had collected around him, \"Have you gathered to take out the arrow?\" When they told him that it was already taken out, he informed them that he had no feeling of pain during the extraction.\n\nMuslim bin Yasaar (Rahmatullah alaih), when he stood up for salaat, said to his family members, \"You may keep on talking; I shall not be aware of what you talk.\"\n\nIt is said of Aamir bin Abdullah (Rahmatullah alaih) that he would not even hear the beating of a drum while in salaat, nor to speak of the talk of people around him. A person asked him, \"Are you conscious of anything while in salaat?\" He replied, \"Yes, I am conscious of the fact that I have to stand one day before Allah, whence I shall either be sent to Paradise or Hell.\" The person said, \"No, I do not mean that. Do you come to know of anything we talk around you?\" He replied, \"It is better that spears pass through my body rather than I grow conscious of your conversation while I am in salaat.\" He used to say, \"My conviction in the things of the Hereafter is so perfect that it is impossible for it to improve, even if I happen to see those things with my physical eyes.\"\n\nA pious man was asked, \"Do you ever think of this world while you are in salaat?\" He replied, \"I never think of this world, either in salaat or out of it.\" Another such man was asked, \"Do you think of anything while in salaat?\" He replied, \"Is there anything more attractive than salaat itself to think of?\"\n\nIn ''Bahjatun Nufoos'' it is written about a Shaikh that he had either been offering fardh or nafl salaat or been absorbed in Zikr without break, right from Zuhr to Fajr of the next day. After Fajr, while continuing Zikr, he was overpowered by slumber, when immediately he recited Istighfaar and the following prayer:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 102"}, {"id": "f1020200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أَعُوذُ بِاللَّهِ مِنْ عَيْنٍ لَا تَشْبَعُ مِنَ النَّوْمِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 102"}, {"id": "f1020300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"I seek refuge in Allah from the eye that does not get satiated with sleep.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 102"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e1030000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 103, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "103", "printedPageNumber": 103, "pdfPageNumber": 486, "sequenceIndex": 93, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b1030100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "AN IMPORTANT NOTE", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f1030000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 103"}, {"id": "f1030100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said about another Shaikh that he would go to bed and try to sleep. But when he failed in his attempt, he would rise up and engage himself in salaat and would say, \"O Allah! Thou knowest very well that it is the fear of the Fire of Hell that has caused my sleep to disappear.\"\n\nThere are so many stories about the pious people spending their nights praying in eagerness and love for Allah that these cannot possibly be covered in one book. We have in fact lost the taste for the pleasures of such pursuits; so much so, we have begun to doubt the veracity of such facts. But these have been related so frequently and continuously that if we doubt them we can as well doubt history, for frequency and continuity in narration about an event vouch safe its correctness without dispute.\n\nAgain we see with our own eyes people spending the whole night (sometimes even standing) for witnessing a show in a cinema or a theatre. They neither get tired nor does sleep overpower them. When such impious deeds, if indulged in, have such an attraction, then what makes us doubt that the spiritual pursuits can be so attractive and tasteful, while persons partaking in them are specially endowed with additional strength and endurance by Allah? The only reason for our doubt is our ignorance, which is like that of an immature child about the experiences of puberty. May Allah enable us to attain the heights where we may be able to taste the pleasures of His worship.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 103"}, {"id": "f1030200-0000-4000-8000-000000000001", "structuralNodeId": "b1030100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "AN IMPORTANT NOTE", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 103"}, {"id": "f1030300-0000-4000-8000-000000000001", "structuralNodeId": "b1030100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "According to the Soofia, salaat is in fact a supplication to and speech with Allah, and therefore needs thorough concentration. In case of other observances, we need not be so attentive. For example, the essence of Zakaat is to spend money for the pleasure of Allah. Spending, in itself is so hard on a person that even if he does it inattentively he would feel the pinch of it. Similarly, fasting requires giving up eating and drinking and sexual satisfaction. All these restrictions are really very hard, even if not observed by proper attention and devotion. On the other hand, Zikr and recitation of the Qur''an are the chief constituents of Salaat. If these are not done intelligently and attentively, they can make neither supplication nor speech. They are just like the ravings of a person in high fever, which do not require any conscious effort nor carry any meaning for the listener. It is therefore necessary that we should be completely at-", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 103"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e1040000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 104, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "104", "printedPageNumber": 104, "pdfPageNumber": 487, "sequenceIndex": 94, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f1040000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 104"}, {"id": "f1040100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "tentive when in salaat, otherwise our salaat will be like the talk of a person in his sleep, which carries no meaning for the listeners, nor any benefit accrues from it. In the same way, Allah pays no heed to a salaat that is offered inattentively and without concentration. But even if our salaat is not up to the mark, as compared with that of the eminent people in the past, we should not give up the practice. It is absolutely incorrect to think that there is no use offering a salaat unless it is perfect. To offer an imperfect salaat is far better than to give it up completely, as this shall result in punishments of a very drastic nature in the Hereafter. A school of Ulama have declared that person to be a kaafir who intentionally discards salaat (as discussed in full in Chapter I).\n\nIt is therefore imperative on all of us to make sincere and genuine efforts to do justice to our salaat and pray to Allah to grant us the ability to offer salaat similar to that of the eminent people in the past, so that we may have at least one salaat of that nature to our credit for presentation before Allah.\n\nIn the end, it may be pointed out that the Muhadditheen are rather liberal in accepting the authenticity of the ahaadith relating to the rewards of different religious observances. As for the stories about saints and pious people, these are a part of ordinary history and therefore on a different footing.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 104"}, {"id": "f1040200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ وَصَلَّى اللَّهُ تَعَالَى عَلَى مَنْ مِلَّتُهُ عَيْنُ الْقَانِتِينَ وَالْمُتَّقِينَ وَعَلَى آلِهِ وَأَصْحَابِهِ وَأَتْبَاعِهِ وَحَمَلَةِ الدِّينِ أَجْمَعِينَ بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 104"}]}'::jsonb);
